window.GRAMMAR_PAGES = {"1":{"line":"Every noun is <b>masculine</b> (le, un) or <b>feminine</b> (la, une), even a table. Learn each noun with its article. Endings help: <b>-age, -ment, -eau</b> are usually masculine; <b>-tion, -té, -ure</b> usually feminine. Plural: add <b>-s</b> (not heard); -eau → -eaux, -al → -aux.","words":"Everyday nouns with pictures: <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:17\">Vocab 17 · The « Survival 50 » Nouns</a>.","steps":[{"tool":"sort","title":"Masculine or feminine?","sub":"Tap the box for each noun. The ending is a clue, with a few traps.","boxes":[{"k":"m","label":"le / un","sub":"masculine"},{"k":"f","label":"la / une","sub":"feminine"}],"cards":[{"t":"fromage","box":"m","why":"-age: usually masculine, <b>le fromage</b>.","en":"cheese"},{"t":"nation","box":"f","why":"-tion: feminine, <b>la nation</b>.","en":"nation"},{"t":"gouvernement","box":"m","why":"-ment: masculine, <b>le gouvernement</b>.","en":"government"},{"t":"liberté","box":"f","why":"-té: feminine, <b>la liberté</b>.","en":"freedom"},{"t":"bateau","box":"m","why":"-eau: masculine, <b>le bateau</b>.","en":"boat"},{"t":"voiture","box":"f","why":"-ure: feminine, <b>la voiture</b>.","en":"car"},{"t":"plage","box":"f","why":"A trap: -age but feminine, <b>la plage</b>.","en":"beach"},{"t":"problème","box":"m","why":"A trap: -e but masculine, <b>le problème</b>.","en":"problem"},{"t":"maison","box":"f","why":"<b>la maison</b>: learn it with la.","en":"house"}]},{"tool":"agree","title":"One or more?","sub":"Switch to the plural: the letters that change light up. The -s is written, not heard.","cols":["one","more than one"],"rows":[{"forms":["le livre","les livres"],"en":["the book","the books"]},{"forms":["la table","les tables"],"en":["the table","the tables"]},{"forms":["le gâteau","les gâteaux"],"en":["the cake","the cakes · -eau → -eaux"]},{"forms":["le journal","les journaux"],"en":["the newspaper","the newspapers · -al → -aux"]},{"forms":["le prix","les prix"],"en":["the price","the prices · -x stays"]},{"forms":["le nez","les nez"],"en":["the nose","the noses · -z stays"]}]},{"tool":"flip","title":"A man, a woman","sub":"Tap a card: the job or the person turns feminine.","cards":[{"a":"un étudiant","b":"une étudiante","tag":"+ e"},{"a":"un acteur","b":"une actrice","tag":"-teur → -trice"},{"a":"un chanteur","b":"une chanteuse","tag":"-eur → -euse"},{"a":"un Italien","b":"une Italienne","tag":"-en → -enne"},{"a":"un boulanger","b":"une boulangère","tag":"-er → -ère"},{"a":"un journaliste","b":"une journaliste","tag":"-e: no change"}]}],"practice":{"choose":[{"q":"___ fromage","en":"cheese","opts":["le","la"],"a":"le","why":"What does -age usually take?","hint":"-age is usually masculine: <b>le fromage</b>."},{"q":"___ nation","en":"nation","opts":["la","le"],"a":"la","why":"What does -tion take?","hint":"-tion is feminine: <b>la nation</b>."},{"q":"___ problème","en":"problem","opts":["le","la"],"a":"le","why":"It ends in -e, but it is one of the traps.","hint":"<b>le problème</b>: masculine."},{"q":"___ plage","en":"beach","opts":["la","le"],"a":"la","why":"It ends in -age, but it is one of the traps.","hint":"<b>la plage</b>: feminine."},{"q":"le gâteau → les ___","en":"the cakes","opts":["gâteaux","gâteaus","gâteau"],"a":"gâteaux","why":"What does -eau take in the plural?","hint":"-eau → <b>-eaux</b>."},{"q":"le journal → les ___","en":"the newspapers","opts":["journaux","journals","journales"],"a":"journaux","why":"What does -al become?","hint":"-al → <b>-aux</b>."},{"q":"un acteur → une ___","en":"an actress","opts":["actrice","acteuse","acteure"],"a":"actrice","why":"-teur has its own feminine.","hint":"-teur → <b>-trice</b>."}],"build":[{"en":"The newspapers are on the table.","tiles":["Les","journaux","sont","sur","la","table."],"trap":"journals","why":"-al in the plural…","hint":"les <b>journaux</b>."},{"en":"She is a student.","tiles":["C'est","une","étudiante."],"trap":"un","why":"She: the feminine.","hint":"<b>une</b> étudiante."},{"en":"I like cakes.","tiles":["J'aime","les","gâteaux."],"trap":"gâteaus","why":"-eau in the plural…","hint":"les <b>gâteaux</b>."},{"en":"The problem is simple.","tiles":["Le","problème","est","simple."],"trap":"La","why":"problème is a trap.","hint":"<b>le</b> problème."},{"en":"The beach is beautiful.","tiles":["La","plage","est","belle."],"trap":"Le","why":"plage is a trap.","hint":"<b>la</b> plage."}],"spot":[{"words":["J'aime","la","fromage."],"bad":1,"fix":"le","hint":"<b>le</b> fromage (-age).","look":"Look at the article."},{"words":["Les","journals","sont là."],"bad":1,"fix":"journaux","hint":"-al → <b>-aux</b>.","look":"Look at the plural."},{"words":["C'est","un","actrice."],"bad":1,"fix":"une","hint":"actrice is a woman: <b>une</b>.","look":"Look at the article."},{"words":["Le","plage","est loin."],"bad":0,"fix":"La","hint":"<b>la</b> plage.","look":"Look at the article."},{"words":["Il y a","deux","gâteau."],"bad":2,"fix":"gâteaux.","hint":"Two cakes: <b>gâteaux</b>.","look":"Two of them…"}]},"drill":[["Which article? ___ plage","la plage","-age is usually masculine, but plage is feminine: <b>la plage</b>."],["Plural of le journal","les journaux","-al → <b>-aux</b>: les journaux."],["Plural of le prix","les prix","Nouns in -s, -x or -z do not change: les prix."],["Feminine of un acteur","une actrice","-teur → <b>-trice</b>."],["Plural of le gâteau","les gâteaux","-eau → <b>-eaux</b>."],["Which article? ___ problème","le problème","A trap: -e but masculine, <b>le problème</b>."]]},"27":{"line":"Cities take <b>à</b>: à Paris. Feminine countries (most end in -e) take <b>en</b>: en France. Masculine ones take <b>au</b> (à + le): au Canada. Plural ones take <b>aux</b>: aux États-Unis. From: de Paris, de France, <b>du</b> Canada, <b>des</b> États-Unis.","words":"The countries and nationalities: <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:10\">Vocab 10 · Les Nationalités & Pays</a>.","steps":[{"tool":"join","title":"à + the country","sub":"Tap a pair: au and aux are à + le and à + les; a feminine country takes en.","pairs":[{"a":"à","b":"le Canada","res":"au Canada","ex":"J'habite au Canada.","en":"I live in Canada."},{"a":"à","b":"les États-Unis","res":"aux États-Unis","ex":"Elle vit aux États-Unis.","en":"She lives in the United States."},{"a":"à","b":"la France","res":"en France","ex":"Nous allons en France.","en":"We are going to France."},{"a":"à","b":"l'Italie","res":"en Italie","ex":"Il travaille en Italie.","en":"He works in Italy."},{"a":"à","b":"Paris","res":"à Paris","stay":true,"ex":"Je suis à Paris.","en":"I am in Paris."},{"a":"de","b":"le Japon","res":"du Japon","ex":"Il vient du Japon.","en":"He comes from Japan."},{"a":"de","b":"la France","res":"de France","ex":"Elle revient de France.","en":"She is coming back from France."}]},{"tool":"sort","title":"en, au, aux or à?","sub":"Tap the box for each place. Watch the masculine countries that end in -e.","boxes":[{"k":"en","label":"en","sub":"feminine, or starts with a vowel"},{"k":"au","label":"au","sub":"masculine"},{"k":"aux","label":"aux","sub":"plural"},{"k":"a","label":"à","sub":"a city"}],"cards":[{"t":"France","box":"en","why":"<b>en</b> France (la France)."},{"t":"Canada","box":"au","why":"<b>au</b> Canada (le Canada)."},{"t":"États-Unis","box":"aux","why":"<b>aux</b> États-Unis (les États-Unis)."},{"t":"Paris","box":"a","why":"A city: <b>à</b> Paris."},{"t":"Espagne","box":"en","why":"<b>en</b> Espagne (l'Espagne)."},{"t":"Japon","box":"au","why":"<b>au</b> Japon (le Japon)."},{"t":"Mexique","box":"au","why":"A trap: -e but masculine: <b>au</b> Mexique."},{"t":"Iran","box":"en","why":"A vowel: <b>en</b> Iran."},{"t":"Pays-Bas","box":"aux","why":"<b>aux</b> Pays-Bas."},{"t":"Londres","box":"a","why":"A city: <b>à</b> Londres."},{"t":"Portugal","box":"au","why":"<b>au</b> Portugal."},{"t":"Cambodge","box":"au","why":"A trap: -e but masculine: <b>au</b> Cambodge."}]},{"tool":"flip","title":"Going to → coming from","sub":"Tap a card: « to » turns into « from ».","cards":[{"a":"Je vais en France.","b":"Je viens de France.","tag":"en → de"},{"a":"Je vais au Canada.","b":"Je viens du Canada.","tag":"au → du"},{"a":"Je vais aux États-Unis.","b":"Je viens des États-Unis.","tag":"aux → des"},{"a":"Je vais à Paris.","b":"Je viens de Paris.","tag":"à → de"},{"a":"Je vais en Italie.","b":"Je viens d'Italie.","tag":"en → d'"},{"a":"Je vais au Japon.","b":"Je viens du Japon.","tag":"au → du"}]}],"practice":{"choose":[{"q":"J'habite ___ France.","en":"I live in France.","opts":["en","au","à","aux"],"a":"en","why":"la France is feminine.","hint":"Feminine country: <b>en</b>."},{"q":"Nous allons ___ Canada.","en":"We are going to Canada.","opts":["au","en","à","aux"],"a":"au","why":"le Canada is masculine.","hint":"à + le = <b>au</b>."},{"q":"Elle vit ___ États-Unis.","en":"She lives in the United States.","opts":["aux","au","en","à"],"a":"aux","why":"les États-Unis is plural.","hint":"à + les = <b>aux</b>."},{"q":"Il travaille ___ Paris.","en":"He works in Paris.","opts":["à","en","au","dans"],"a":"à","why":"Paris is a city.","hint":"A city: <b>à</b>."},{"q":"Je vais ___ Mexique.","en":"I am going to Mexico.","opts":["au","en","à","aux"],"a":"au","why":"It ends in -e, but le Mexique is masculine.","hint":"<b>au</b> Mexique."},{"q":"Il vient ___ Japon.","en":"He comes from Japan.","opts":["du","de","des","au"],"a":"du","why":"From + le Japon…","hint":"de + le = <b>du</b>."},{"q":"Elle revient ___ Italie.","en":"She is coming back from Italy.","opts":["d'","de","du","en"],"a":"d'","why":"Italie starts with a vowel.","hint":"<b>d'</b>Italie."}],"build":[{"en":"I live in Spain.","tiles":["J'habite","en","Espagne."],"trap":"au","why":"l'Espagne is feminine.","hint":"<b>en</b> Espagne."},{"en":"We are going to Portugal.","tiles":["Nous","allons","au","Portugal."],"trap":"en","why":"le Portugal is masculine.","hint":"<b>au</b> Portugal."},{"en":"She comes from the United States.","tiles":["Elle","vient","des","États-Unis."],"trap":"de les","why":"de + les join.","hint":"<b>des</b> États-Unis."},{"en":"He works in London.","tiles":["Il","travaille","à","Londres."],"trap":"en","why":"London is a city.","hint":"<b>à</b> Londres."},{"en":"I come from Canada.","tiles":["Je","viens","du","Canada."],"trap":"de le","why":"de + le join.","hint":"<b>du</b> Canada."}],"spot":[{"words":["J'habite","au","France."],"bad":1,"fix":"en","hint":"Feminine country: <b>en</b> France.","look":"Look at the little word before France."},{"words":["Nous allons","en","Canada."],"bad":1,"fix":"au","hint":"Masculine country: <b>au</b> Canada.","look":"Look at the little word before Canada."},{"words":["Il vit","en","Paris."],"bad":1,"fix":"à","hint":"A city: <b>à</b> Paris.","look":"Is Paris a country or a city?"},{"words":["Elle vient","de les","États-Unis."],"bad":1,"fix":"des","hint":"de + les = <b>des</b>.","look":"Two little words that should join."},{"words":["Je vais","en","Mexique."],"bad":1,"fix":"au","hint":"<b>au</b> Mexique: masculine, although it ends in -e.","look":"Mexique is one of the traps."}]},"drill":[["I live in France","J'habite en France. / Je vis en France.","Feminine country: <b>en</b> France."],["We are going to Canada","Nous allons au Canada.","Masculine country: à + le = <b>au</b> Canada."],["She comes from the United States","Elle vient des États-Unis.","From a plural country: de + les = <b>des</b>."],["He lives in Japan","Il habite au Japon. / Il vit au Japon.","le Japon: <b>au</b> Japon."],["I'm going to Spain.","Je vais en Espagne.","l'Espagne is feminine: <b>en</b> Espagne."],["He comes from Japan.","Il vient du Japon.","de + le = <b>du</b> Japon."]]},"3":{"line":"« Some » of something you can't count: <b>du</b> (le), <b>de la</b> (la), <b>de l'</b> (before a vowel), <b>des</b> (plural): je bois du café, de l'eau. English often says nothing; French always does. After a no: <b>pas de</b>. After a quantity: <b>beaucoup de</b>, un kilo de. Likes take le: j'aime le café.","words":"Food and ordering: <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:18\">Vocab 18 · Café, Food & Ordering</a>.","steps":[{"tool":"join","title":"de + the article","sub":"Tap a pair: de + le and de + les join; de la and de l' stay.","pairs":[{"a":"de","b":"le pain","res":"du pain","ex":"Je mange du pain.","en":"I eat (some) bread."},{"a":"de","b":"la confiture","res":"de la confiture","stay":true,"ex":"Tu veux de la confiture ?","en":"Do you want (some) jam?"},{"a":"de","b":"l'eau","res":"de l'eau","stay":true,"ex":"Je bois de l'eau.","en":"I drink water."},{"a":"de","b":"les pâtes","res":"des pâtes","ex":"On mange des pâtes ce soir.","en":"We are having pasta tonight."}]},{"tool":"sort","title":"Some of it, or all of it?","sub":"Tap the box: an amount (some) or the thing in general (likes and dislikes)?","boxes":[{"k":"some","label":"du / de la / des","sub":"some, an amount"},{"k":"all","label":"le / la / les","sub":"in general: aimer, adorer, détester"}],"cards":[{"t":"Je bois … café le matin.","box":"some","why":"An amount you drink: <b>du</b> café.","say":"Je bois du café le matin."},{"t":"J'adore … café.","box":"all","why":"Likes take le: <b>le</b> café.","say":"J'adore le café."},{"t":"Tu veux … pain ?","box":"some","why":"Some bread: <b>du</b> pain.","say":"Tu veux du pain ?"},{"t":"Je déteste … fromage.","box":"all","why":"Dislikes take le: <b>le</b> fromage.","say":"Je déteste le fromage."},{"t":"On achète … pommes.","box":"some","why":"Some apples: <b>des</b> pommes.","say":"On achète des pommes."},{"t":"Les enfants aiment … chocolat.","box":"all","why":"Likes take le: <b>le</b> chocolat.","say":"Les enfants aiment le chocolat."}]},{"tool":"flip","title":"After a no, after a quantity","sub":"Tap a card: du, de la, des become de.","cards":[{"a":"Je bois du café.","b":"Je ne bois pas de café.","tag":"du → pas de"},{"a":"Il y a de la soupe.","b":"Il n'y a pas de soupe.","tag":"de la → pas de"},{"a":"Elle mange des pommes.","b":"Elle mange beaucoup de pommes.","tag":"des → beaucoup de"},{"a":"J'achète du fromage.","b":"J'achète un kilo de fromage.","tag":"du → un kilo de"},{"a":"Il boit de l'eau.","b":"Il ne boit pas d'eau.","tag":"de l' → pas d'"}]}],"practice":{"choose":[{"q":"Je voudrais ___ eau.","en":"I'd like some water.","opts":["de l'","du","de la","des"],"a":"de l'","why":"eau starts with a vowel.","hint":"<b>de l'</b>eau."},{"q":"Tu veux ___ pain ?","en":"Do you want some bread?","opts":["du","de la","le","des"],"a":"du","why":"le pain: some of it…","hint":"de + le = <b>du</b>."},{"q":"Elle mange ___ salade.","en":"She is eating (some) salad.","opts":["de la","du","la","des"],"a":"de la","why":"la salade: some of it…","hint":"<b>de la</b> salade."},{"q":"J'aime ___ fromage.","en":"I like cheese.","opts":["le","du","de","un"],"a":"le","why":"Liking something: some, or in general?","hint":"Likes take <b>le</b>."},{"q":"Il ne mange pas ___ viande.","en":"He doesn't eat meat.","opts":["de","de la","la","du"],"a":"de","why":"It is a no.","hint":"After a no: <b>pas de</b>."},{"q":"Il y a beaucoup ___ gens.","en":"There are a lot of people.","opts":["de","des","du","les"],"a":"de","why":"After beaucoup…","hint":"<b>beaucoup de</b>."},{"q":"On achète ___ tomates.","en":"We are buying (some) tomatoes.","opts":["des","de","les","du"],"a":"des","why":"Some tomatoes, more than one.","hint":"<b>des</b> tomates."}],"build":[{"en":"I drink water.","tiles":["Je","bois","de l'","eau."],"trap":"du","why":"eau starts with a vowel.","hint":"<b>de l'</b>eau."},{"en":"She doesn't eat meat.","tiles":["Elle","ne","mange","pas","de","viande."],"trap":"de la","why":"It is a no.","hint":"pas <b>de</b> viande."},{"en":"Do you want some bread?","tiles":["Tu","veux","du","pain ?"],"trap":"de le","why":"de + le join.","hint":"<b>du</b> pain."},{"en":"There are a lot of people.","tiles":["Il","y a","beaucoup","de","monde."],"trap":"du","why":"After beaucoup…","hint":"beaucoup <b>de</b>."},{"en":"I like chocolate.","tiles":["J'aime","le","chocolat."],"trap":"du","why":"Likes take le.","hint":"j'aime <b>le</b> chocolat."}],"spot":[{"words":["Je","bois","de le","café."],"bad":2,"fix":"du","hint":"de + le = <b>du</b>.","look":"Two little words that should join."},{"words":["Elle","ne mange pas","de la","viande."],"bad":2,"fix":"de","hint":"After a no: <b>pas de</b>.","look":"Look at the word after pas."},{"words":["J'aime","du","chocolat."],"bad":1,"fix":"le","hint":"Likes take <b>le</b>.","look":"With aimer, which article?"},{"words":["Il y a","beaucoup","des","gens."],"bad":2,"fix":"de","hint":"<b>beaucoup de</b>, never beaucoup des.","look":"Look at the word after beaucoup."},{"words":["Je voudrais","du","eau."],"bad":1,"fix":"de l'","hint":"eau starts with a vowel: <b>de l'</b>eau.","look":"eau starts with a vowel.","say":"Je voudrais de l'eau."}]},"drill":[["I'd like some water","Je voudrais de l'eau. / J'aimerais de l'eau.","Before a vowel: <b>de l'</b>eau."],["She doesn't eat meat","Elle ne mange pas de viande.","After a no: <b>pas de</b>."],["a lot of people","beaucoup de monde / beaucoup de gens","After beaucoup: <b>de</b>."],["Do you want some bread?","Tu veux du pain ? / Vous voulez du pain ? / Veux-tu du pain ?","de + le = <b>du</b> pain."],["I like cheese.","J'aime le fromage.","Likes take <b>le</b>: j'aime le fromage."],["There isn't any milk.","Il n'y a pas de lait.","After a no: <b>pas de</b> lait."]]},"4":{"line":"French verbs need a subject: <b>je</b> (j' before a vowel), <b>tu, il, elle, on, nous, vous, ils, elles</b>. <b>tu</b> = one person you know well; <b>vous</b> = polite, or more than one person. <b>ils</b> for a group with at least one man, <b>elles</b> only women. Things are il or elle too. <b>on</b> = we, in everyday French.","words":"","steps":[{"tool":"sort","title":"tu or vous?","sub":"Who are you talking to? Tap the box.","boxes":[{"k":"tu","label":"tu","sub":"one person you know well"},{"k":"vous","label":"vous","sub":"polite, or more than one"}],"cards":[{"t":"your best friend","box":"tu","why":"A friend: <b>tu</b>."},{"t":"your boss","box":"vous","why":"Polite: <b>vous</b>."},{"t":"a child","box":"tu","why":"A child: <b>tu</b>."},{"t":"a waiter in a café","box":"vous","why":"Someone you do not know: <b>vous</b>."},{"t":"your mother","box":"tu","why":"Family: <b>tu</b>."},{"t":"two friends together","box":"vous","why":"More than one person: <b>vous</b>, even friends."},{"t":"a doctor","box":"vous","why":"Polite: <b>vous</b>."}]},{"tool":"sort","title":"il, elle, ils or elles?","sub":"Tap the pronoun for each one.","boxes":[{"k":"il","label":"il"},{"k":"elle","label":"elle"},{"k":"ils","label":"ils"},{"k":"elles","label":"elles"}],"cards":[{"t":"Paul","box":"il"},{"t":"Marie","box":"elle"},{"t":"Marie et Julie","box":"elles","why":"Only women: <b>elles</b>."},{"t":"Marie et Paul","box":"ils","why":"One man is enough: <b>ils</b>."},{"t":"le livre","box":"il","why":"Things too: le livre → <b>il</b>."},{"t":"la table","box":"elle","why":"la table → <b>elle</b>."},{"t":"les enfants (girls and boys)","box":"ils","why":"Mixed: <b>ils</b>."},{"t":"les filles","box":"elles"}]},{"tool":"flip","title":"je → j', and on","sub":"Tap a card. Before a vowel or a silent h, je becomes j'. In everyday French, on means we.","cards":[{"a":"je + aime","b":"j'aime","tag":"je → j'"},{"a":"je + habite","b":"j'habite","tag":"silent h: j'"},{"a":"je + écoute","b":"j'écoute","tag":"je → j'"},{"a":"je + parle","b":"je parle","tag":"no vowel: no change"},{"a":"Nous allons au cinéma.","b":"On va au cinéma.","tag":"nous → on (everyday)"}]}],"practice":{"choose":[{"q":"Marie et Julie → ___","en":"","opts":["elles","ils","elle","vous"],"a":"elles","why":"Two women…","hint":"Only women: <b>elles</b>."},{"q":"Marie et Paul → ___","en":"","opts":["ils","elles","il","on"],"a":"ils","why":"There is a man in the group.","hint":"One man is enough: <b>ils</b>."},{"q":"« ___ êtes prêt, monsieur ? »","en":"Are you ready, sir?","opts":["Vous","Tu","Il","Nous"],"a":"Vous","why":"Talking to « monsieur »…","hint":"Polite: <b>vous</b>."},{"q":"« ___ viens ce soir ? » (to a friend)","en":"Are you coming tonight?","opts":["Tu","Vous","Il","Je"],"a":"Tu","why":"A friend…","hint":"A friend: <b>tu</b>."},{"q":"___ aime le café. (I)","en":"I like coffee.","opts":["J'","Je","Tu","Il"],"a":"J'","why":"aime starts with a vowel.","hint":"Before a vowel: <b>j'</b>aime."},{"q":"Le livre ? ___ est sur la table.","en":"The book? It is on the table.","opts":["Il","Elle","Le","On"],"a":"Il","why":"le livre is masculine.","hint":"le livre → <b>il</b>."},{"q":"La voiture ? ___ est rouge.","en":"The car? It is red.","opts":["Elle","Il","La","On"],"a":"Elle","why":"la voiture is feminine.","hint":"la voiture → <b>elle</b>."}],"build":[{"en":"We're going to the cinema (everyday French).","tiles":["On","va","au","cinéma."],"trap":"allons","why":"on takes the il form.","hint":"<b>on va</b>."},{"en":"I live in Lyon.","tiles":["J'habite","à","Lyon."],"trap":"Je","why":"habite starts with a silent h.","hint":"<b>j'</b>habite."},{"en":"They (Marie and Paul) are here.","tiles":["Ils","sont","là."],"trap":"Elles","why":"There is a man in the group.","hint":"<b>ils</b> sont là."},{"en":"Are you ready, sir?","tiles":["Vous","êtes","prêt,","monsieur ?"],"trap":"Tu","why":"Polite…","hint":"<b>vous</b> êtes."},{"en":"She is tired.","tiles":["Elle","est","fatiguée."],"trap":"Il","why":"She…","hint":"<b>elle</b> est."}],"spot":[{"words":["Je aime","le chocolat."],"bad":0,"fix":"J'aime","hint":"Before a vowel: <b>j'</b>aime.","look":"aime starts with a vowel."},{"words":["Marie et Paul,","elles","sont là."],"bad":1,"fix":"ils","hint":"One man is enough: <b>ils</b>.","look":"Look at who is in the group."},{"words":["Monsieur,","tu","êtes","en retard."],"bad":1,"fix":"vous","hint":"Polite, and êtes is the vous form: <b>vous</b>.","look":"Look at the verb: which pronoun does it go with?"},{"words":["On","allons","au parc."],"bad":1,"fix":"va","hint":"on takes the il form: <b>on va</b>.","look":"Look at the verb after on."},{"words":["La table ?","Il","est","grande."],"bad":1,"fix":"Elle","hint":"la table → <b>elle</b>.","look":"Is table masculine or feminine?"}]},"drill":[["Speaking to your boss: tu or vous?","vous","Polite: <b>vous</b>."],["Marie and Julie","elles","Only women: <b>elles</b>."],["Marie and Paul","ils","One man is enough: <b>ils</b>."],["je + aime","J'aime","Before a vowel, je becomes <b>j'</b>."],["Le livre → pronoun","il","Things are il or elle too: le livre → <b>il</b>."],["je + habite","J'habite","A silent h counts as a vowel: <b>j'</b>habite."]]},"29":{"line":"<b>moi, toi, lui, elle, nous, vous, eux, elles</b> stand on their own. Use them after <b>c'est</b> (c'est moi), after a little word like <b>avec, chez, pour</b> (avec toi, chez lui), to stress (<b>Moi</b>, je préfère le thé), and in short answers (Moi aussi, Moi non plus).","words":"","steps":[{"tool":"swap","title":"Put the stress on it","sub":"Pick a sentence and tap « Stress it »: the stressed pronoun comes to the front.","button":["Stress it","Plain again"],"legend":[["p","the stressed pronoun"]],"items":[{"label":"Je préfère le thé.","en":["I prefer tea.","Me, I prefer tea."],"a":[["s","Je",""],["v","préfère",""],["o","le thé.",""]],"b":[["m","Moi,","p"],["s","je",""],["v","préfère",""],["o","le thé.",""]],"note":"<b>Moi</b> at the front puts the weight on « I »."},{"label":"Tu as raison.","en":["You are right.","You, you are right."],"a":[["s","Tu",""],["v","as",""],["o","raison.",""]],"b":[["m","Toi,","p"],["s","tu",""],["v","as",""],["o","raison.",""]],"note":"tu → <b>toi</b>."},{"label":"Il est grand.","en":["He is tall.","Him, he is tall."],"a":[["s","Il",""],["v","est",""],["o","grand.",""]],"b":[["m","Lui,","p"],["s","il",""],["v","est",""],["o","grand.",""]],"note":"il → <b>lui</b>."},{"label":"Ils sont partis.","en":["They left.","Them, they left."],"a":[["s","Ils",""],["v","sont",""],["o","partis.",""]],"b":[["m","Eux,","p"],["s","ils",""],["v","sont",""],["o","partis.",""]],"note":"ils → <b>eux</b> (men, or a mixed group)."}]},{"tool":"flip","title":"After c'est and little words","sub":"Tap a card: the subject pronoun turns into its stressed form.","cards":[{"a":"je","b":"C'est moi.","tag":"je → moi"},{"a":"tu","b":"avec toi","tag":"tu → toi"},{"a":"il","b":"chez lui","tag":"il → lui"},{"a":"elle","b":"pour elle","tag":"elle → elle"},{"a":"nous","b":"sans nous","tag":"nous → nous"},{"a":"ils","b":"avec eux","tag":"ils → eux"},{"a":"elles","b":"chez elles","tag":"elles → elles"}]},{"tool":"pairs","title":"Short answers","sub":"Agreeing with a yes, and with a no. Tap one to hear it.","cap":["Agreeing with a yes","Agreeing with a no"],"rows":[{"l":"J'aime le café. Moi aussi.","r":"Je n'aime pas le café. Moi non plus.","en":"me too / me neither"},{"l":"Il est content. Moi aussi.","r":"Il n'est pas content. Moi non plus."},{"l":"Nous partons. Nous aussi.","r":"Nous ne partons pas. Nous non plus."}]}],"practice":{"choose":[{"q":"C'est ___ ! (me)","en":"It's me!","opts":["moi","je","me","mon"],"a":"moi","why":"After c'est…","hint":"c'est <b>moi</b>."},{"q":"Je viens avec ___. (you, tu)","en":"I'm coming with you.","opts":["toi","tu","te","ton"],"a":"toi","why":"After avec…","hint":"avec <b>toi</b>."},{"q":"Elle habite chez ___. (him)","en":"She lives at his place.","opts":["lui","il","le","son"],"a":"lui","why":"After chez…","hint":"chez <b>lui</b>."},{"q":"Je travaille avec ___. (them, men)","en":"I work with them.","opts":["eux","ils","leur","les"],"a":"eux","why":"After avec, ils becomes…","hint":"avec <b>eux</b>."},{"q":"___, je préfère le thé.","en":"Me, I prefer tea.","opts":["Moi","Je","Me","Mon"],"a":"Moi","why":"Stress at the front…","hint":"<b>Moi</b>, je …"},{"q":"« J'aime ce film. » « ___ aussi. »","en":"« Me too. »","opts":["Moi","Je","Me","Mon"],"a":"Moi","why":"A short answer stands on its own.","hint":"<b>Moi</b> aussi."},{"q":"« Je n'ai pas faim. » « Moi ___. »","en":"« Me neither. »","opts":["non plus","aussi","pas","non"],"a":"non plus","why":"Agreeing with a no…","hint":"Moi <b>non plus</b>."}],"build":[{"en":"It's me.","tiles":["C'est","moi."],"trap":"je","why":"After c'est…","hint":"c'est <b>moi</b>."},{"en":"I'm coming with you.","tiles":["Je","viens","avec","toi."],"trap":"tu","why":"After avec…","hint":"avec <b>toi</b>."},{"en":"Paul is taller than him.","tiles":["Paul","est","plus","grand","que","lui."],"trap":"il","why":"After que…","hint":"que <b>lui</b>."},{"en":"Me too.","tiles":["Moi","aussi."],"trap":"Je","why":"A short answer…","hint":"<b>Moi</b> aussi."},{"en":"I'm going home.","tiles":["Je","rentre","chez","moi."],"trap":"je","why":"After chez…","hint":"chez <b>moi</b>."}],"spot":[{"words":["C'est","je."],"bad":1,"fix":"moi.","hint":"After c'est: <b>moi</b>.","look":"Look at the word after c'est."},{"words":["Je pars","avec","tu."],"bad":2,"fix":"toi.","hint":"After avec: <b>toi</b>.","look":"Look at the word after avec."},{"words":["Il dîne","chez","il."],"bad":2,"fix":"lui.","hint":"After chez: <b>lui</b>.","look":"Look at the word after chez."},{"words":["Je","aussi."],"bad":0,"fix":"Moi","hint":"A short answer: <b>Moi</b> aussi.","look":"Can je stand on its own?","say":"Moi aussi."},{"words":["Je travaille","avec","ils."],"bad":2,"fix":"eux.","hint":"After avec, ils becomes <b>eux</b>.","look":"Look at the word after avec."}]},"drill":[["It's me","C'est moi.","After c'est: <b>moi</b>."],["with you (tu)","avec toi","After avec: <b>toi</b>."],["taller than him","plus grand que lui","After que: <b>lui</b>."],["Me too","Moi aussi.","A short answer: <b>Moi</b> aussi."],["at their place (men)","chez eux","After chez, ils becomes <b>eux</b>."],["Me neither.","Moi non plus.","Agreeing with a no: moi <b>non plus</b>."]]},"v1":{"line":"<b>être</b> (to be): je suis, tu es, il est, nous sommes, vous êtes, ils sont. <b>avoir</b> (to have): j'ai, tu as, il a, nous avons, vous avez, ils ont. Learn them as whole words: they have no regular pattern. Listen: <b>ils ont</b> (a z sound) and <b>ils sont</b> (an s sound) are different verbs.","words":"","steps":[{"tool":"conj","title":"être and avoir","sub":"Pick the verb, then tap a person. Tap ne … pas for the no.","neg":true,"verbs":[{"inf":"être","en":"to be","forms":["suis","es","est","sommes","êtes","sont"],"tail":"à Paris"},{"inf":"avoir","en":"to have","forms":["ai","as","a","avons","avez","ont"],"tail":"un chat"}]},{"tool":"sort","title":"être or avoir?","sub":"Tap the verb each sentence needs.","boxes":[{"k":"etre","label":"être","sub":"who or what someone is"},{"k":"avoir","label":"avoir","sub":"having, age, hunger, fear…"}],"cards":[{"t":"Je … étudiant.","box":"etre","why":"Who you are: <b>je suis</b> étudiant.","say":"Je suis étudiant."},{"t":"J'… vingt ans.","box":"avoir","why":"Age: <b>j'ai</b> vingt ans.","say":"J'ai vingt ans."},{"t":"Elle … fatiguée.","box":"etre","why":"How she is: <b>elle est</b> fatiguée.","say":"Elle est fatiguée."},{"t":"Nous … faim.","box":"avoir","why":"Hunger: <b>nous avons</b> faim.","say":"Nous avons faim."},{"t":"Ils … de Lyon.","box":"etre","why":"Where from: <b>ils sont</b> de Lyon.","say":"Ils sont de Lyon."},{"t":"Tu … un chat ?","box":"avoir","why":"Having: <b>tu as</b> un chat ?","say":"Tu as un chat ?"},{"t":"Il … médecin.","box":"etre","why":"A job: <b>il est</b> médecin.","say":"Il est médecin."},{"t":"Vous … raison.","box":"avoir","why":"<b>vous avez</b> raison.","say":"Vous avez raison."}]},{"tool":"pairs","title":"ils ont or ils sont?","sub":"They sound close. Tap each one: avoir has a z sound, être an s sound.","cap":["avoir: ils ont (z)","être: ils sont (s)"],"rows":[{"l":"Ils ont faim.","r":"Ils sont fatigués.","en":"they are hungry / they are tired"},{"l":"Elles ont vingt ans.","r":"Elles sont contentes."},{"l":"Ils ont une maison.","r":"Ils sont à la maison."}]}],"practice":{"choose":[{"q":"Nous ___ fatigués.","en":"We are tired.","opts":["sommes","avons","êtes","sont"],"a":"sommes","why":"How we are: être, and nous.","hint":"être: nous <b>sommes</b>."},{"q":"Ils ___ une grande maison.","en":"They have a big house.","opts":["ont","sont","avons","a"],"a":"ont","why":"Having: avoir, and ils.","hint":"avoir: ils <b>ont</b>."},{"q":"Vous ___ en retard.","en":"You are late.","opts":["êtes","avez","es","sont"],"a":"êtes","why":"être, and vous.","hint":"être: vous <b>êtes</b>."},{"q":"J'___ deux frères.","en":"I have two brothers.","opts":["ai","suis","as","es"],"a":"ai","why":"Having: avoir, with j'.","hint":"avoir: <b>j'ai</b>."},{"q":"Tu ___ canadien ?","en":"Are you Canadian?","opts":["es","as","est","a"],"a":"es","why":"Where from: être, and tu.","hint":"être: tu <b>es</b>."},{"q":"Elle ___ trente ans.","en":"She is thirty.","opts":["a","est","as","ai"],"a":"a","why":"Age takes avoir.","hint":"avoir: elle <b>a</b>."},{"q":"Je ___ médecin.","en":"I am a doctor.","opts":["suis","ai","es","sommes"],"a":"suis","why":"A job: être.","hint":"être: je <b>suis</b>."}],"build":[{"en":"We are from Lyon.","tiles":["Nous","sommes","de","Lyon."],"trap":"avons","why":"Where from: être.","hint":"nous <b>sommes</b>."},{"en":"They have a big house.","tiles":["Ils","ont","une","grande","maison."],"trap":"sont","why":"Having: avoir.","hint":"ils <b>ont</b>."},{"en":"You (vous) are late.","tiles":["Vous","êtes","en retard."],"trap":"avez","why":"être late…","hint":"vous <b>êtes</b>."},{"en":"I have two brothers.","tiles":["J'ai","deux","frères."],"trap":"Je suis","why":"Having: avoir.","hint":"<b>j'ai</b>."},{"en":"She is a doctor.","tiles":["Elle","est","médecin."],"trap":"a","why":"A job: être.","hint":"elle <b>est</b>."}],"spot":[{"words":["Nous","avons","fatigués."],"bad":1,"fix":"sommes","hint":"How we are: <b>nous sommes</b>.","look":"Is fatigués something you have?"},{"words":["Ils","sont","une voiture."],"bad":1,"fix":"ont","hint":"Having: <b>ils ont</b>.","look":"Look at the verb."},{"words":["Je ai","faim."],"bad":0,"fix":"J'ai","hint":"<b>j'ai</b>: je becomes j' before a vowel.","look":"Look at the first word."},{"words":["Vous","êtes","raison."],"bad":1,"fix":"avez","hint":"avoir raison: <b>vous avez</b> raison.","look":"Right is something you have."},{"words":["Tu","est","content ?"],"bad":1,"fix":"es","hint":"être with tu: <b>tu es</b>.","look":"Look at the verb with tu."}]},"drill":[["we are (être)","nous sommes","être: nous <b>sommes</b>."],["they have (avoir)","ils ont","avoir: ils <b>ont</b> (a z sound)."],["you (vous) are","vous êtes","être: vous <b>êtes</b>."],["I have","j'ai","avoir: <b>j'ai</b>."],["she is (être)","elle est","être: il / elle <b>est</b>."],["you (tu) have","tu as","avoir: tu <b>as</b>."]]},"v2":{"line":"<b>aller</b> (to go): je vais, tu vas, il va, nous allons, vous allez, ils vont. <b>faire</b> (to do, to make): je fais, tu fais, il fait, nous faisons (said « fesons »), vous faites, ils font. aller + a verb = the near future (je vais manger). faire is in the weather (il fait beau) and in sports (je fais du vélo).","words":"The weather with faire: <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:8\">Vocab 8 · La Météo & Les Saisons</a>.","steps":[{"tool":"conj","title":"aller and faire","sub":"Pick the verb, then tap a person. Tap ne … pas for the no.","neg":true,"verbs":[{"inf":"aller","en":"to go","forms":["vais","vas","va","allons","allez","vont"],"tail":"au marché"},{"inf":"faire","en":"to do, to make","forms":["fais","fais","fait","faisons","faites","font"],"tail":"du sport"}]},{"tool":"sort","title":"aller or faire?","sub":"Tap the verb each sentence needs.","boxes":[{"k":"aller","label":"aller","sub":"going somewhere, the near future"},{"k":"faire","label":"faire","sub":"doing, making, the weather, sport"}],"cards":[{"t":"Je … au cinéma.","box":"aller","why":"<b>je vais</b> au cinéma.","say":"Je vais au cinéma."},{"t":"Il … beau.","box":"faire","why":"The weather: <b>il fait</b> beau.","say":"Il fait beau."},{"t":"Nous … du vélo.","box":"faire","why":"Sport: <b>nous faisons</b> du vélo.","say":"Nous faisons du vélo."},{"t":"Ils … partir.","box":"aller","why":"The near future: <b>ils vont</b> partir.","say":"Ils vont partir."},{"t":"Tu … la cuisine ?","box":"faire","why":"<b>tu fais</b> la cuisine ?","say":"Tu fais la cuisine ?"},{"t":"Vous … à Paris ?","box":"aller","why":"<b>vous allez</b> à Paris ?","say":"Vous allez à Paris ?"},{"t":"Elle … ses devoirs.","box":"faire","why":"<b>elle fait</b> ses devoirs.","say":"Elle fait ses devoirs."}]},{"tool":"flip","title":"Expressions with faire","sub":"Tap a card: the expression in a sentence.","cards":[{"a":"faire beau","b":"Il fait beau.","tag":"the weather is nice"},{"a":"faire froid","b":"Il fait froid.","tag":"it is cold"},{"a":"faire du sport","b":"Je fais du sport.","tag":"I do sport"},{"a":"faire la cuisine","b":"Il fait la cuisine.","tag":"he cooks"},{"a":"faire les courses","b":"Nous faisons les courses.","tag":"we do the shopping"},{"a":"faire attention","b":"Fais attention !","tag":"be careful"}]}],"practice":{"choose":[{"q":"Je ___ au marché.","en":"I am going to the market.","opts":["vais","va","vas","allons"],"a":"vais","why":"aller with je.","hint":"je <b>vais</b>."},{"q":"Nous ___ du sport.","en":"We do sport.","opts":["faisons","faites","font","fais"],"a":"faisons","why":"faire with nous.","hint":"nous <b>faisons</b>."},{"q":"Vous ___ la cuisine ?","en":"Are you cooking?","opts":["faites","faisez","fait","font"],"a":"faites","why":"faire with vous: an irregular one.","hint":"vous <b>faites</b>."},{"q":"Ils ___ à Lyon.","en":"They are going to Lyon.","opts":["vont","allent","vas","font"],"a":"vont","why":"aller with ils.","hint":"ils <b>vont</b>."},{"q":"Il ___ beau aujourd'hui.","en":"The weather is nice today.","opts":["fait","est","va","a"],"a":"fait","why":"The weather takes…","hint":"il <b>fait</b> beau."},{"q":"Tu ___ où ?","en":"Where are you going?","opts":["vas","va","vais","allez"],"a":"vas","why":"aller with tu.","hint":"tu <b>vas</b>."},{"q":"Elles ___ les courses.","en":"They do the shopping.","opts":["font","faisent","vont","fait"],"a":"font","why":"faire with elles.","hint":"elles <b>font</b>."}],"build":[{"en":"We are going to the market.","tiles":["Nous","allons","au","marché."],"trap":"allez","why":"aller with nous.","hint":"nous <b>allons</b>."},{"en":"The weather is nice.","tiles":["Il","fait","beau."],"trap":"est","why":"The weather takes faire.","hint":"il <b>fait</b> beau."},{"en":"They do sport.","tiles":["Ils","font","du","sport."],"trap":"faisent","why":"faire with ils is irregular.","hint":"ils <b>font</b>."},{"en":"You (vous) do the shopping.","tiles":["Vous","faites","les","courses."],"trap":"faisez","why":"faire with vous is irregular.","hint":"vous <b>faites</b>."},{"en":"I'm going home.","tiles":["Je","vais","à","la","maison."],"trap":"va","why":"aller with je.","hint":"je <b>vais</b>."}],"spot":[{"words":["Vous","faisez","du vélo."],"bad":1,"fix":"faites","hint":"vous <b>faites</b>.","look":"Look at the verb with vous."},{"words":["Ils","allent","au cinéma."],"bad":1,"fix":"vont","hint":"ils <b>vont</b>.","look":"Look at the verb with ils."},{"words":["Il","est","froid."],"bad":1,"fix":"fait","hint":"The weather: il <b>fait</b> froid.","look":"It is about the weather."},{"words":["Je","va","à Paris."],"bad":1,"fix":"vais","hint":"je <b>vais</b>.","look":"Look at the verb with je."},{"words":["Ils","faisent","la cuisine."],"bad":1,"fix":"font","hint":"ils <b>font</b>.","look":"Look at the verb with ils."}]},"drill":[["I go","je vais","aller: je <b>vais</b>."],["we do (faire)","nous faisons","faire: nous <b>faisons</b> (said « fesons »)."],["you (vous) do","vous faites","faire: vous <b>faites</b> (not faisez)."],["they go","ils vont","aller: ils <b>vont</b>."],["it's cold (the weather)","il fait froid","The weather takes <b>faire</b>: il fait froid."],["she goes","elle va","aller: il / elle <b>va</b>."]]},"5":{"line":"Take off -er, -ir or -re, then add the endings. <b>-er</b> (parler): je parle, tu parles, il parle, nous parlons, vous parlez, ils parlent; -e, -es and -ent are not heard. <b>-ir</b> (finir): je finis, nous finissons, ils finissent. <b>-re</b> (vendre): je vends, il vend, nous vendons. Je parle = I speak, I am speaking and I do speak.","words":"Every verb in full: <a class=\"text-indigo-700 font-semibold underline\" href=\"conjugations.html\">Conjugations</a>.","steps":[{"tool":"conj","title":"The three families","sub":"Pick a verb, then tap a person: the ending lights up. Grey endings are written but not heard.","neg":true,"verbs":[{"inf":"parler","en":"to speak","stem":"parl","forms":["parle","parles","parle","parlons","parlez","parlent"],"silent":[true,true,true,false,false,true],"tail":"français"},{"inf":"aimer","en":"to like","stem":"aim","forms":["aime","aimes","aime","aimons","aimez","aiment"],"silent":[true,true,true,false,false,true],"tail":"le café"},{"inf":"finir","en":"to finish","stem":"fin","forms":["finis","finis","finit","finissons","finissez","finissent"],"tail":"à six heures"},{"inf":"vendre","en":"to sell","stem":"vend","forms":["vends","vends","vend","vendons","vendez","vendent"],"tail":"des livres"}]},{"tool":"sort","title":"Which family?","sub":"Tap the family for each verb.","boxes":[{"k":"er","label":"-er","sub":"like parler"},{"k":"ir","label":"-ir","sub":"like finir"},{"k":"re","label":"-re","sub":"like vendre"}],"cards":[{"t":"manger","box":"er","why":"to eat"},{"t":"choisir","box":"ir","why":"to choose: nous choisissons"},{"t":"attendre","box":"re","why":"to wait: j'attends"},{"t":"regarder","box":"er","why":"to watch"},{"t":"réussir","box":"ir","why":"to succeed: ils réussissent"},{"t":"répondre","box":"re","why":"to answer: il répond"},{"t":"habiter","box":"er","why":"to live"},{"t":"entendre","box":"re","why":"to hear"}]},{"tool":"flip","title":"Small spelling changes","sub":"Tap a card to see the right spelling.","cards":[{"a":"nous mangons","b":"nous mangeons","tag":"g + e before o"},{"a":"nous commencons","b":"nous commençons","tag":"c → ç before o"},{"a":"je aime","b":"j'aime","tag":"je → j' before a vowel"},{"a":"ils finent","b":"ils finissent","tag":"-ir: -issent"},{"a":"il vende","b":"il vend","tag":"-re: il vend"}]}],"practice":{"choose":[{"q":"Nous ___ (manger) à midi.","en":"We eat at noon.","opts":["mangeons","mangons","mangez","mangent"],"a":"mangeons","why":"g before o needs a little help.","hint":"nous <b>mangeons</b>."},{"q":"Tu ___ (finir) à cinq heures.","en":"You finish at five.","opts":["finis","finit","fini","finissez"],"a":"finis","why":"-ir with tu.","hint":"tu <b>finis</b>."},{"q":"Ils ___ (vendre) leur maison.","en":"They are selling their house.","opts":["vendent","vendont","vend","vendez"],"a":"vendent","why":"-re with ils.","hint":"ils <b>vendent</b>."},{"q":"Vous ___ (parler) anglais ?","en":"Do you speak English?","opts":["parlez","parlons","parles","parler"],"a":"parlez","why":"-er with vous.","hint":"vous <b>parlez</b>."},{"q":"Elle ___ (choisir) une robe.","en":"She chooses a dress.","opts":["choisit","choisis","choisi","choisissent"],"a":"choisit","why":"-ir with elle.","hint":"elle <b>choisit</b>."},{"q":"J'___ (aimer) le café.","en":"I like coffee.","opts":["aime","aimes","aiment","aimons"],"a":"aime","why":"-er with je.","hint":"j'<b>aime</b>."},{"q":"Ils ___ (finir) tard.","en":"They finish late.","opts":["finissent","finent","finissons","finis"],"a":"finissent","why":"-ir with ils.","hint":"ils <b>finissent</b>."}],"build":[{"en":"I speak French.","tiles":["Je","parle","français."],"trap":"parles","why":"-er with je.","hint":"je <b>parle</b>."},{"en":"We eat at noon.","tiles":["Nous","mangeons","à","midi."],"trap":"mangons","why":"g before o…","hint":"nous <b>mangeons</b>."},{"en":"They finish at six.","tiles":["Ils","finissent","à","six heures."],"trap":"finent","why":"-ir with ils.","hint":"ils <b>finissent</b>."},{"en":"You (tu) are waiting for the bus.","tiles":["Tu","attends","le","bus."],"trap":"attend","why":"-re with tu.","hint":"tu <b>attends</b>."},{"en":"She likes tea.","tiles":["Elle","aime","le","thé."],"trap":"aimes","why":"-er with elle.","hint":"elle <b>aime</b>."}],"spot":[{"words":["Nous","mangons","ensemble."],"bad":1,"fix":"mangeons","hint":"nous <b>mangeons</b>: keep the e.","look":"Look at the spelling with nous."},{"words":["Ils","finent","le travail."],"bad":1,"fix":"finissent","hint":"-ir with ils: <b>finissent</b>.","look":"Look at the verb with ils."},{"words":["Tu","parle","anglais ?"],"bad":1,"fix":"parles","hint":"-er with tu: <b>parles</b>.","look":"Look at the ending with tu."},{"words":["Il","vends","sa voiture."],"bad":1,"fix":"vend","hint":"-re with il: <b>vend</b>.","look":"Look at the ending with il."},{"words":["Je aime","le thé."],"bad":0,"fix":"J'aime","hint":"Before a vowel: <b>j'</b>aime.","look":"Look at the first word."}]},"drill":[["nous (manger)","nous mangeons","Keep the e before o: nous <b>mangeons</b>."],["tu (finir)","tu finis","-ir: tu <b>finis</b>."],["ils (vendre)","ils vendent","-re: ils <b>vendent</b>."],["I like coffee","J'aime le café.","j'<b>aime</b>, and likes take le."],["vous (parler)","vous parlez","-er: vous <b>-ez</b>."],["elle (choisir)","elle choisit","-ir: il / elle <b>-it</b>."]]},"v3":{"line":"<b>vouloir</b> (want), <b>pouvoir</b> (can), <b>devoir</b> (must), <b>savoir</b> (know how to) + a second verb that stays as it is: je <b>veux</b> partir, tu <b>peux</b> venir, il <b>doit</b> travailler, je <b>sais</b> nager. Only the first verb changes. To be polite: je <b>voudrais</b>.","words":"","steps":[{"tool":"conj","title":"The four modal verbs","sub":"Pick a verb, then tap a person. The second verb never changes.","neg":true,"verbs":[{"inf":"vouloir","en":"to want","forms":["veux","veux","veut","voulons","voulez","veulent"],"tail":"partir"},{"inf":"pouvoir","en":"can","forms":["peux","peux","peut","pouvons","pouvez","peuvent"],"tail":"venir"},{"inf":"devoir","en":"must","forms":["dois","dois","doit","devons","devez","doivent"],"tail":"travailler"},{"inf":"savoir","en":"to know how to","forms":["sais","sais","sait","savons","savez","savent"],"tail":"nager"}]},{"tool":"swap","title":"The second verb stays as it is","sub":"Pick a sentence and tap « Add the modal »: the first verb changes, the second goes back to its -er, -ir or -re form.","button":["Add the modal","Take it away"],"legend":[["x","the modal (it changes)"],["v","stays as it is"],["n","ne … pas"]],"items":[{"label":"Je pars.","en":["I am leaving.","I want to leave."],"a":[["s","Je",""],["v","pars.","v"]],"b":[["s","Je",""],["m","veux","x"],["v","partir.","v"]],"note":"Only <b>veux</b> changes; partir stays as it is."},{"label":"Tu viens ?","en":["Are you coming?","Can you come?"],"a":[["s","Tu",""],["v","viens ?","v"]],"b":[["s","Tu",""],["m","peux","x"],["v","venir ?","v"]],"note":"<b>peux</b> + venir."},{"label":"Il travaille.","en":["He works.","He must work."],"a":[["s","Il",""],["v","travaille.","v"]],"b":[["s","Il",""],["m","doit","x"],["v","travailler.","v"]],"note":"<b>doit</b> + travailler."},{"label":"Je nage.","en":["I swim.","I know how to swim."],"a":[["s","Je",""],["v","nage.","v"]],"b":[["s","Je",""],["m","sais","x"],["v","nager.","v"]],"note":"<b>sais</b> + nager."},{"label":"Nous ne partons pas.","en":["We are not leaving.","We don't want to leave."],"a":[["s","Nous",""],["ne","ne","n"],["v","partons","v"],["pas","pas.","n"]],"b":[["s","Nous",""],["ne","ne","n"],["m","voulons","x"],["pas","pas","n"],["v","partir.","v"]],"note":"The no goes round the <b>first</b> verb: ne voulons pas partir."}]},{"tool":"flip","title":"Polite: je voudrais","sub":"Tap a card: the softer, more polite way to ask.","cards":[{"a":"Je veux un café.","b":"Je voudrais un café.","tag":"more polite"},{"a":"Tu peux m'aider ?","b":"Tu pourrais m'aider ?","tag":"softer"},{"a":"Vous pouvez répéter ?","b":"Vous pourriez répéter ?","tag":"softer"},{"a":"Je veux réserver une table.","b":"Je voudrais réserver une table.","tag":"more polite"}]}],"practice":{"choose":[{"q":"Je ___ partir. (want)","en":"I want to leave.","opts":["veux","voulez","veut","voulons"],"a":"veux","why":"vouloir with je.","hint":"je <b>veux</b>."},{"q":"Nous ___ venir demain. (can)","en":"We can come tomorrow.","opts":["pouvons","peuvons","pouvez","peux"],"a":"pouvons","why":"pouvoir with nous.","hint":"nous <b>pouvons</b>."},{"q":"Tu ___ travailler. (must)","en":"You must work.","opts":["dois","doit","devoir","devez"],"a":"dois","why":"devoir with tu.","hint":"tu <b>dois</b>."},{"q":"Ils ___ nager. (know how to)","en":"They know how to swim.","opts":["savent","savons","sait","peuvent"],"a":"savent","why":"savoir with ils.","hint":"ils <b>savent</b>."},{"q":"Je veux ___.","en":"I want to leave.","opts":["partir","pars","part","partons"],"a":"partir","why":"The second verb…","hint":"It stays as it is: <b>partir</b>."},{"q":"Elle ne ___ pas venir. (can)","en":"She can't come.","opts":["peut","peux","pouvoir","peuvent"],"a":"peut","why":"pouvoir with elle.","hint":"elle <b>peut</b>."},{"q":"Je ___ un café, s'il vous plaît. (would like)","en":"I'd like a coffee, please.","opts":["voudrais","veux","voulez","voudrait"],"a":"voudrais","why":"The polite form with je.","hint":"je <b>voudrais</b>."}],"build":[{"en":"I want to leave.","tiles":["Je","veux","partir."],"trap":"pars","why":"The second verb stays as it is.","hint":"veux <b>partir</b>."},{"en":"Can you help me?","tiles":["Tu","peux","m'aider ?"],"trap":"aides","why":"The second verb stays as it is.","hint":"peux <b>m'aider</b>."},{"en":"We must work.","tiles":["Nous","devons","travailler."],"trap":"travaillons","why":"The second verb stays as it is.","hint":"devons <b>travailler</b>."},{"en":"She can't come.","tiles":["Elle","ne","peut","pas","venir."],"trap":"vient","why":"The no goes round the first verb.","hint":"ne <b>peut</b> pas venir."},{"en":"I'd like a coffee.","tiles":["Je","voudrais","un","café."],"trap":"veux","why":"The polite form…","hint":"je <b>voudrais</b>."}],"spot":[{"words":["Je","veux","pars."],"bad":2,"fix":"partir.","hint":"The second verb stays as it is: <b>partir</b>.","look":"Look at the second verb."},{"words":["Ils","peuvent","venons."],"bad":2,"fix":"venir.","hint":"The second verb stays as it is: <b>venir</b>.","look":"Look at the second verb."},{"words":["Tu","doit","partir."],"bad":1,"fix":"dois","hint":"devoir with tu: <b>dois</b>.","look":"Look at the first verb with tu."},{"words":["Elle","ne veut","partir pas."],"bad":2,"fix":"pas partir.","hint":"pas goes after the first verb: ne veut <b>pas</b> partir.","look":"Where does pas go?"},{"words":["Ils","savons","nager."],"bad":1,"fix":"savent","hint":"savoir with ils: <b>savent</b>.","look":"Look at the first verb with ils."}]},"drill":[["I want (vouloir)","je veux","vouloir: je <b>veux</b>."],["we can (pouvoir)","nous pouvons","pouvoir: nous <b>pouvons</b>."],["you (tu) must (devoir)","tu dois","devoir: tu <b>dois</b>."],["they know (savoir)","ils savent","savoir: ils <b>savent</b>."],["I want to leave.","Je veux partir.","The second verb stays as it is: <b>partir</b>."],["I'd like a coffee.","Je voudrais un café.","Polite: <b>je voudrais</b>."]]},"v6":{"line":"Learn one model and you know its family. <b>prendre</b>: je prends, nous prenons, ils prennent (→ comprendre, apprendre). <b>venir</b>: je viens, nous venons, ils viennent (→ devenir, revenir). <b>partir</b>: je pars, nous partons (→ sortir, dormir). <b>boire</b>: je bois, nous buvons, ils boivent.","words":"Every verb in full: <a class=\"text-indigo-700 font-semibold underline\" href=\"conjugations.html\">Conjugations</a>.","steps":[{"tool":"conj","title":"Four models","sub":"Pick a verb, then tap a person. Tap ne … pas for the no.","neg":true,"verbs":[{"inf":"prendre","en":"to take","forms":["prends","prends","prend","prenons","prenez","prennent"],"tail":"le train"},{"inf":"venir","en":"to come","forms":["viens","viens","vient","venons","venez","viennent"],"tail":"demain"},{"inf":"partir","en":"to leave","forms":["pars","pars","part","partons","partez","partent"],"tail":"à huit heures"},{"inf":"boire","en":"to drink","forms":["bois","bois","boit","buvons","buvez","boivent"],"tail":"de l'eau"}]},{"tool":"sort","title":"Which model?","sub":"Tap the model each verb follows.","boxes":[{"k":"prendre","label":"like prendre"},{"k":"venir","label":"like venir"},{"k":"partir","label":"like partir"}],"cards":[{"t":"comprendre","box":"prendre","why":"to understand: je comprends, ils comprennent"},{"t":"apprendre","box":"prendre","why":"to learn: j'apprends"},{"t":"devenir","box":"venir","why":"to become: il devient"},{"t":"revenir","box":"venir","why":"to come back: ils reviennent"},{"t":"sortir","box":"partir","why":"to go out: je sors, nous sortons"},{"t":"dormir","box":"partir","why":"to sleep: je dors, nous dormons"},{"t":"tenir","box":"venir","why":"to hold: je tiens, ils tiennent"},{"t":"surprendre","box":"prendre","why":"to surprise: il surprend"}]},{"tool":"flip","title":"Same family, same endings","sub":"Tap a card: the model turns into a verb of its family.","cards":[{"a":"je prends","b":"je comprends","tag":"prendre → comprendre"},{"a":"ils viennent","b":"ils deviennent","tag":"venir → devenir"},{"a":"nous partons","b":"nous sortons","tag":"partir → sortir"},{"a":"tu prends","b":"tu apprends","tag":"prendre → apprendre"},{"a":"il vient","b":"il revient","tag":"venir → revenir"},{"a":"je pars","b":"je dors","tag":"partir → dormir"}]}],"practice":{"choose":[{"q":"Je ___ le bus. (prendre)","en":"I take the bus.","opts":["prends","prend","prenons","prennent"],"a":"prends","why":"prendre with je.","hint":"je <b>prends</b>."},{"q":"Nous ___ du thé. (boire)","en":"We drink tea.","opts":["buvons","boivons","boisons","buvez"],"a":"buvons","why":"boire with nous has its own stem.","hint":"nous <b>buvons</b>."},{"q":"Ils ___ demain. (venir)","en":"They are coming tomorrow.","opts":["viennent","venent","vient","venons"],"a":"viennent","why":"venir with ils: double n.","hint":"ils <b>viennent</b>."},{"q":"Tu ___ à quelle heure ? (partir)","en":"What time are you leaving?","opts":["pars","part","partes","partez"],"a":"pars","why":"partir with tu.","hint":"tu <b>pars</b>."},{"q":"Vous ___ le français ? (comprendre)","en":"Do you understand French?","opts":["comprenez","comprendez","comprennent","comprends"],"a":"comprenez","why":"Like prendre with vous.","hint":"vous <b>comprenez</b>."},{"q":"Elles ___ le train. (prendre)","en":"They take the train.","opts":["prennent","prenent","prendent","prend"],"a":"prennent","why":"prendre with elles: double n.","hint":"elles <b>prennent</b>."},{"q":"Il ___ beaucoup. (dormir)","en":"He sleeps a lot.","opts":["dort","dors","dorme","dormit"],"a":"dort","why":"Like partir with il.","hint":"il <b>dort</b>."}],"build":[{"en":"I take the train.","tiles":["Je","prends","le","train."],"trap":"prend","why":"prendre with je.","hint":"je <b>prends</b>."},{"en":"They are coming tomorrow.","tiles":["Ils","viennent","demain."],"trap":"venent","why":"venir with ils.","hint":"ils <b>viennent</b>."},{"en":"We drink water.","tiles":["Nous","buvons","de l'","eau."],"trap":"boivons","why":"boire with nous.","hint":"nous <b>buvons</b>."},{"en":"You (tu) leave at eight.","tiles":["Tu","pars","à","huit heures."],"trap":"part","why":"partir with tu.","hint":"tu <b>pars</b>."},{"en":"Do you understand French?","tiles":["Vous","comprenez","le","français ?"],"trap":"comprendez","why":"Like prendre with vous.","hint":"vous <b>comprenez</b>."}],"spot":[{"words":["Ils","prendent","le bus."],"bad":1,"fix":"prennent","hint":"prendre with ils: <b>prennent</b>.","look":"Look at the verb with ils."},{"words":["Nous","boivons","du café."],"bad":1,"fix":"buvons","hint":"boire with nous: <b>buvons</b>.","look":"Look at the verb with nous."},{"words":["Elles","venent","ce soir."],"bad":1,"fix":"viennent","hint":"venir with elles: <b>viennent</b>.","look":"Look at the verb with elles."},{"words":["Je","part","demain."],"bad":1,"fix":"pars","hint":"partir with je: <b>pars</b>.","look":"Look at the ending with je."},{"words":["Vous","comprendez ?"],"bad":1,"fix":"comprenez ?","hint":"Like prendre: vous <b>comprenez</b>.","look":"Look at the verb with vous."}]},"drill":[["I take (prendre)","je prends","prendre: je <b>prends</b>."],["we drink (boire)","nous buvons","boire: nous <b>buvons</b>."],["they come (venir)","ils viennent","venir: ils <b>viennent</b>."],["you (tu) leave (partir)","tu pars","partir: tu <b>pars</b>."],["you (vous) understand (comprendre)","vous comprenez","Like prendre: vous prenez → vous <b>comprenez</b>."],["they drink (boire)","ils boivent","boire: ils <b>boivent</b>."]]},"7":{"line":"Three ways to ask the same yes/no question: <b>Tu viens ?</b> (your voice goes up: everyday), <b>Est-ce que tu viens ?</b> (everyday, very clear), <b>Viens-tu ?</b> (verb first with a hyphen: formal). With il or elle and a vowel, add <b>-t-</b>: A-t-il faim ? Question words go first or, in casual French, last: Où tu habites ? Tu habites où ?","words":"Où, quand, comment…: <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:2\">Vocab 2 · Question Words</a>.","steps":[{"tool":"swap","title":"Make it a question","sub":"Pick a sentence and tap « Make it a question ».","button":["Make it a question","Back to the sentence"],"legend":[["x","added"],["v","the verb"]],"items":[{"label":"Tu viens. (voice up)","en":["You are coming.","Are you coming?"],"a":[["s","Tu",""],["v","viens.","v"]],"b":[["s","Tu",""],["v","viens ?","v"]],"note":"Same words: only your voice goes up. Everyday French."},{"label":"Vous habitez à Paris. (est-ce que)","en":["You live in Paris.","Do you live in Paris?"],"a":[["s","Vous",""],["v","habitez","v"],["o","à Paris.",""]],"b":[["q","Est-ce que","x"],["s","vous",""],["v","habitez","v"],["o","à Paris ?",""]],"note":"<b>Est-ce que</b> at the front: clear, and everyday."},{"label":"Tu as faim. (verb first)","en":["You are hungry.","Are you hungry?"],"a":[["s","Tu",""],["v","as","v"],["o","faim.",""]],"b":[["v","As-","v"],["s","tu",""],["o","faim ?",""]],"note":"The verb jumps first, with a hyphen: <b>As-tu</b> faim ? Formal."},{"label":"Il parle anglais. (-t-)","en":["He speaks English.","Does he speak English?"],"a":[["s","Il",""],["v","parle","v"],["o","anglais.",""]],"b":[["v","Parle-","v"],["t","t-","x"],["s","il",""],["o","anglais ?",""]],"note":"Two vowels meet (parle / il): add <b>-t-</b>."},{"label":"Tu habites à Lyon. (où)","en":["You live in Lyon.","Where do you live?"],"a":[["s","Tu",""],["v","habites","v"],["o","à Lyon.",""]],"b":[["s","Tu",""],["v","habites","v"],["w","où ?","x"]],"note":"Casual: the question word goes at the end. Also: <b>Où est-ce que</b> tu habites ?"}]},{"tool":"sort","title":"Casual, everyday or formal?","sub":"Tap the box for each question.","boxes":[{"k":"c","label":"Casual","sub":"only the voice goes up"},{"k":"e","label":"Everyday","sub":"est-ce que"},{"k":"f","label":"Formal","sub":"the verb first"}],"cards":[{"t":"Tu viens ce soir ?","box":"c"},{"t":"Est-ce que tu viens ?","box":"e"},{"t":"Viens-tu ce soir ?","box":"f"},{"t":"Vous parlez anglais ?","box":"c"},{"t":"Parlez-vous anglais ?","box":"f"},{"t":"Est-ce qu'il a faim ?","box":"e","why":"Before a vowel: est-ce <b>qu'</b>il."},{"t":"A-t-il faim ?","box":"f","why":"-t- between two vowels."},{"t":"Tu habites où ?","box":"c"}]}],"practice":{"choose":[{"q":"___ tu viens ?","en":"Are you coming?","opts":["Est-ce que","Est-ce","Que","Qu'est-ce"],"a":"Est-ce que","why":"The everyday question starter…","hint":"<b>Est-ce que</b> tu viens ?"},{"q":"___-tu faim ?","en":"Are you hungry?","opts":["As","A","Es","Ai"],"a":"As","why":"avoir with tu, verb first.","hint":"<b>As</b>-tu faim ?"},{"q":"Parle-___-il anglais ?","en":"Does he speak English?","opts":["t","s","l","il"],"a":"t","why":"Two vowels meet.","hint":"Parle-<b>t</b>-il ?"},{"q":"___ qu'elle est là ?","en":"Is she here?","opts":["Est-ce","Est-ce que","Est","Que"],"a":"Est-ce","why":"qu' is already there.","hint":"<b>Est-ce</b> qu'elle est là ?"},{"q":"Tu habites ___ ? (where)","en":"Where do you live?","opts":["où","ou","quand","qui"],"a":"où","why":"where, with its accent…","hint":"<b>où</b> (with an accent) = where; ou = or."},{"q":"___-vous français ?","en":"Are you French?","opts":["Êtes","Es","Est","Sont"],"a":"Êtes","why":"être with vous, verb first.","hint":"<b>Êtes</b>-vous français ?"},{"q":"Où ___ vous habitez ?","en":"Where do you live?","opts":["est-ce que","est-ce","que","qu'"],"a":"est-ce que","why":"After a question word…","hint":"Où <b>est-ce que</b> vous habitez ?"}],"build":[{"en":"Do you live in Paris? (est-ce que)","tiles":["Est-ce que","vous","habitez","à","Paris ?"],"trap":"Est-ce","why":"The whole starter…","hint":"<b>Est-ce que</b> vous …"},{"en":"Does he speak English? (verb first)","tiles":["Parle-t-il","anglais ?"],"trap":"Parle-il","why":"Two vowels meet.","hint":"<b>Parle-t-il</b> …"},{"en":"Where do you live? (casual)","tiles":["Tu","habites","où ?"],"trap":"ou","why":"where, with its accent.","hint":"… <b>où</b> ?"},{"en":"Is she here? (est-ce que)","tiles":["Est-ce","qu'elle","est","là ?"],"trap":"que elle","why":"Before a vowel…","hint":"Est-ce <b>qu'elle</b> …"},{"en":"Are you French? (verb first, vous)","tiles":["Êtes-vous","français ?"],"trap":"Es-vous","why":"être with vous.","hint":"<b>Êtes-vous</b> …"}],"spot":[{"words":["Parle-il","anglais ?"],"bad":0,"fix":"Parle-t-il","hint":"Two vowels meet: <b>-t-</b>.","look":"Look between the verb and il."},{"words":["Est-ce que","elle","vient ?"],"bad":0,"fix":"Est-ce qu'","hint":"Before a vowel: est-ce <b>qu'</b>elle.","look":"What happens to que before a vowel?","say":"Est-ce qu'elle vient ?"},{"words":["Tu","habites","ou ?"],"bad":2,"fix":"où ?","hint":"<b>où</b> = where (ou = or).","look":"Look at the question word."},{"words":["A-il","faim ?"],"bad":0,"fix":"A-t-il","hint":"Two vowels meet: <b>A-t-il</b>.","look":"Look between a and il."},{"words":["Est-ce","tu","viens ?"],"bad":0,"fix":"Est-ce que","hint":"The whole starter: <b>Est-ce que</b>.","look":"Something is missing at the start."}]},"drill":[["Est-ce que form: Vous habitez à Paris.","Est-ce que vous habitez à Paris ?","<b>Est-ce que</b> at the front."],["Invert: Tu as faim.","As-tu faim ?","Verb first, with a hyphen: <b>As-tu</b> …?"],["Invert: Il parle anglais.","Parle-t-il anglais ?","Two vowels meet: add <b>-t-</b>."],["Where do you live? (casual)","Tu habites où ?","Casual: the question word at the end."],["Est-ce que form: Elle est là.","Est-ce qu'elle est là ?","Before a vowel: est-ce <b>qu'</b>elle."],["Invert: Vous êtes français.","Êtes-vous français ?","Verb first: <b>Êtes-vous</b> …?"]]},"8":{"line":"An adjective matches its noun: <b>+e</b> for feminine, <b>+s</b> for plural (petit, petite, petits, petites). Most go <b>after</b> the noun: une voiture rouge. A few short ones go <b>before</b>: beauty, age, good, size (BAGS): une belle maison, un jeune homme, un bon ami, une petite ville. Watch: blanc → blanche, beau → bel before a vowel.","words":"Describing people: <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:12\">Vocab 12 · Personality & Physical Description</a> · colours: <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:14\">Vocab 14 · Les Couleurs</a>.","steps":[{"tool":"agree","title":"Switch the noun","sub":"Tap masculine, feminine or plural: what changes lights up.","cols":["masculine","feminine","masc. plural","fem. plural"],"rows":[{"forms":["un chat noir","une chatte noire","des chats noirs","des chattes noires"],"en":"a black cat"},{"forms":["un petit garçon","une petite fille","des petits garçons","des petites filles"],"en":"a little boy / girl"},{"forms":["un ami content","une amie contente","des amis contents","des amies contentes"],"en":"a happy friend"},{"forms":["un homme heureux","une femme heureuse","des hommes heureux","des femmes heureuses"],"en":"-eux → -euse"},{"forms":["un pull blanc","une robe blanche","des pulls blancs","des robes blanches"],"en":"blanc → blanche"},{"forms":["un livre rouge","une voiture rouge","des livres rouges","des voitures rouges"],"en":"-e already: no new e"}]},{"tool":"sort","title":"Before or after the noun?","sub":"Tap the box for each adjective.","boxes":[{"k":"b","label":"before","sub":"BAGS: beauty, age, good, size"},{"k":"a","label":"after","sub":"most: colour, nationality, shape, feelings"}],"cards":[{"t":"petit","box":"b","why":"Size: une <b>petite</b> ville."},{"t":"rouge","box":"a","why":"Colour: une voiture <b>rouge</b>."},{"t":"jeune","box":"b","why":"Age: un <b>jeune</b> homme."},{"t":"français","box":"a","why":"Nationality: un film <b>français</b>."},{"t":"bon","box":"b","why":"Good: un <b>bon</b> ami."},{"t":"intéressant","box":"a","why":"un livre <b>intéressant</b>."},{"t":"beau","box":"b","why":"Beauty: un <b>beau</b> jardin."},{"t":"rond","box":"a","why":"Shape: une table <b>ronde</b>."},{"t":"vieux","box":"b","why":"Age: un <b>vieux</b> livre."}]},{"tool":"flip","title":"Special forms","sub":"Tap a card.","cards":[{"a":"beau + homme","b":"un bel homme","tag":"beau → bel before a vowel"},{"a":"vieux + ami","b":"un vieil ami","tag":"vieux → vieil before a vowel"},{"a":"nouveau + hôtel","b":"un nouvel hôtel","tag":"nouveau → nouvel"},{"a":"blanc (feminine)","b":"blanche","tag":"-c → -che"},{"a":"long (feminine)","b":"longue","tag":"-g → -gue"},{"a":"beau (feminine)","b":"belle","tag":"beau → belle"}]}],"practice":{"choose":[{"q":"une voiture ___ (blanc)","en":"a white car","opts":["blanche","blance","blanc","blanches"],"a":"blanche","why":"blanc has a special feminine.","hint":"<b>blanche</b>."},{"q":"des chats ___ (noir)","en":"black cats","opts":["noirs","noir","noires","noire"],"a":"noirs","why":"Masculine, more than one.","hint":"<b>noirs</b>."},{"q":"un ___ homme (beau)","en":"a handsome man","opts":["bel","beau","belle","beaux"],"a":"bel","why":"homme starts with a silent h.","hint":"<b>bel</b> before a vowel."},{"q":"une ___ maison (petit)","en":"a small house","opts":["petite","petit","petites","petits"],"a":"petite","why":"One, feminine.","hint":"<b>petite</b>."},{"q":"une robe ___ (long)","en":"a long dress","opts":["longue","longe","long","longues"],"a":"longue","why":"long has a special feminine.","hint":"<b>longue</b>."},{"q":"des filles ___ (heureux)","en":"happy girls","opts":["heureuses","heureux","heureuse","heureuxes"],"a":"heureuses","why":"Feminine and more than one.","hint":"<b>heureuses</b>."},{"q":"un ___ ami (vieux)","en":"an old friend","opts":["vieil","vieux","vieille","vieilles"],"a":"vieil","why":"ami starts with a vowel.","hint":"<b>vieil</b> before a vowel."}],"build":[{"en":"I live in a small town.","tiles":["J'habite","dans","une","petite","ville."],"trap":"petit","why":"ville is feminine; petit goes before.","hint":"une <b>petite</b> ville."},{"en":"She has a red car.","tiles":["Elle","a","une","voiture","rouge."],"trap":"rouges","why":"One car; colours go after.","hint":"une voiture <b>rouge</b>."},{"en":"He is a young man.","tiles":["C'est","un","jeune","homme."],"trap":"jeunes","why":"Age goes before.","hint":"un <b>jeune</b> homme."},{"en":"Two happy girls.","tiles":["Deux","filles","heureuses."],"trap":"heureux","why":"Feminine and more than one.","hint":"filles <b>heureuses</b>."},{"en":"It's a beautiful house.","tiles":["C'est","une","belle","maison."],"trap":"beau","why":"maison is feminine.","hint":"une <b>belle</b> maison."}],"spot":[{"words":["une","voiture","blanc."],"bad":2,"fix":"blanche.","hint":"Feminine: <b>blanche</b>.","look":"Does the adjective match voiture?"},{"words":["un","beau","homme."],"bad":1,"fix":"bel","hint":"Before a vowel: <b>bel</b>.","look":"homme starts with a silent h."},{"words":["une","maison petite."],"bad":1,"fix":"petite maison.","hint":"Size goes before: une <b>petite maison</b>.","look":"Where does petit go?"},{"words":["des","chats","noir."],"bad":2,"fix":"noirs.","hint":"More than one: <b>noirs</b>.","look":"How many cats?"},{"words":["une","rouge voiture."],"bad":1,"fix":"voiture rouge.","hint":"Colours go after: une <b>voiture rouge</b>.","look":"Where do colours go?"}]},"drill":[["une voiture (blanc)","une voiture blanche","blanc → <b>blanche</b>."],["des chats (noir)","des chats noirs","Plural: <b>+s</b>."],["un (beau) homme","un bel homme","Before a vowel: <b>bel</b>."],["une maison (petit)","une petite maison","Size goes before, + e: une <b>petite</b> maison."],["une robe (long)","une robe longue","long → <b>longue</b>."],["des filles (heureux)","des filles heureuses","-eux → <b>-euse</b>, plural <b>-euses</b>."]]},"9":{"line":"my: <b>mon / ma / mes</b> · your: ton / ta / tes · his or her: <b>son / sa / ses</b> · our: notre / nos · your: votre / vos · their: leur / leurs. They agree with the <b>thing owned</b>: sa voiture = his car or her car. Before a vowel: <b>mon</b> amie. this: <b>ce / cet</b> (before a vowel) <b>/ cette / ces</b>.","words":"The family: <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:9\">Vocab 9 · La Famille</a>.","steps":[{"tool":"agree","title":"Switch the thing owned","sub":"Tap masculine, feminine or plural: the little word follows the thing, not the owner.","cols":["masculine","feminine","plural"],"rows":[{"forms":["mon frère","ma sœur","mes frères"],"en":["my brother","my sister","my brothers"]},{"forms":["ton père","ta mère","tes parents"],"en":["your father","your mother","your parents"]},{"forms":["son livre","sa voiture","ses clés"],"en":["his / her book","his / her car","his / her keys"]},{"forms":["notre ami","notre amie","nos amis"],"en":["our friend","our friend","our friends"]},{"forms":["leur chat","leur maison","leurs enfants"],"en":["their cat","their house","their children"]},{"forms":["ce livre","cette table","ces livres"],"en":["this book","this table","these books"]}]},{"tool":"sort","title":"son, sa or ses?","sub":"Look at the thing, not at who owns it. Tap the box.","boxes":[{"k":"son","label":"son","sub":"masculine, or before a vowel"},{"k":"sa","label":"sa","sub":"feminine"},{"k":"ses","label":"ses","sub":"more than one"}],"cards":[{"t":"Paul: … voiture","box":"sa","why":"voiture is feminine: <b>sa</b> voiture, even for Paul.","say":"sa voiture"},{"t":"Marie: … vélo","box":"son","why":"vélo is masculine: <b>son</b> vélo, even for Marie.","say":"son vélo"},{"t":"Paul: … sœurs","box":"ses","why":"More than one: <b>ses</b> sœurs.","say":"ses sœurs"},{"t":"Marie: … père","box":"son","why":"<b>son</b> père.","say":"son père"},{"t":"Marie: … amie","box":"son","why":"amie starts with a vowel: <b>son</b> amie.","say":"son amie"},{"t":"Paul: … maison","box":"sa","why":"<b>sa</b> maison.","say":"sa maison"},{"t":"Marie: … livres","box":"ses","why":"<b>ses</b> livres.","say":"ses livres"}]},{"tool":"flip","title":"Before a vowel","sub":"Tap a card: ma, ta, sa and ce change before a vowel.","cards":[{"a":"ma + amie","b":"mon amie","tag":"ma → mon"},{"a":"ta + école","b":"ton école","tag":"ta → ton"},{"a":"sa + histoire","b":"son histoire","tag":"sa → son (silent h)"},{"a":"ce + hôtel","b":"cet hôtel","tag":"ce → cet"},{"a":"ce + arbre","b":"cet arbre","tag":"ce → cet"},{"a":"ce + garçon","b":"ce garçon","tag":"no vowel: no change"}]}],"practice":{"choose":[{"q":"___ sœur (my)","en":"my sister","opts":["ma","mon","mes","me"],"a":"ma","why":"sœur is feminine.","hint":"<b>ma</b> sœur."},{"q":"___ amie (my)","en":"my friend (a woman)","opts":["mon","ma","m'","mes"],"a":"mon","why":"amie starts with a vowel.","hint":"Before a vowel: <b>mon</b> amie."},{"q":"___ hôtel (this)","en":"this hotel","opts":["cet","ce","cette","ces"],"a":"cet","why":"hôtel starts with a silent h.","hint":"<b>cet</b> hôtel."},{"q":"___ maison (this)","en":"this house","opts":["cette","cet","ce","ces"],"a":"cette","why":"maison is feminine.","hint":"<b>cette</b> maison."},{"q":"Paul aime ___ voiture.","en":"Paul loves his car.","opts":["sa","son","ses","leur"],"a":"sa","why":"Look at voiture, not at Paul.","hint":"voiture is feminine: <b>sa</b>."},{"q":"Ils aiment ___ enfants.","en":"They love their children.","opts":["leurs","leur","ses","son"],"a":"leurs","why":"Their, and more than one child.","hint":"<b>leurs</b> enfants."},{"q":"___ livres (these)","en":"these books","opts":["ces","ses","cettes","cet"],"a":"ces","why":"these, not his…","hint":"<b>ces</b> livres (ses = his / her)."}],"build":[{"en":"This is my friend Julie.","tiles":["C'est","mon","amie","Julie."],"trap":"ma","why":"amie starts with a vowel.","hint":"<b>mon</b> amie."},{"en":"Paul washes his car.","tiles":["Paul","lave","sa","voiture."],"trap":"son","why":"voiture is feminine.","hint":"<b>sa</b> voiture."},{"en":"This hotel is big.","tiles":["Cet","hôtel","est","grand."],"trap":"Ce","why":"hôtel starts with a silent h.","hint":"<b>cet</b> hôtel."},{"en":"Their children are here.","tiles":["Leurs","enfants","sont","là."],"trap":"Ses","why":"Their, more than one.","hint":"<b>leurs</b> enfants."},{"en":"I like these shoes.","tiles":["J'aime","ces","chaussures."],"trap":"ses","why":"these…","hint":"<b>ces</b> chaussures."}],"spot":[{"words":["C'est","ma","amie."],"bad":1,"fix":"mon","hint":"Before a vowel: <b>mon</b> amie.","look":"amie starts with a vowel."},{"words":["Ce","hôtel","est loin."],"bad":0,"fix":"Cet","hint":"Before a vowel: <b>cet</b>.","look":"hôtel starts with a silent h."},{"words":["Marie aime","son","voiture."],"bad":1,"fix":"sa","hint":"voiture is feminine: <b>sa</b>.","look":"Look at the thing, not the owner."},{"words":["Ils voient","leur","enfants."],"bad":1,"fix":"leurs","hint":"More than one: <b>leurs</b>.","look":"How many children?"},{"words":["J'aime","cette","livre."],"bad":1,"fix":"ce","hint":"livre is masculine: <b>ce</b>.","look":"Is livre masculine or feminine?"}]},"drill":[["___ sœur (my)","ma sœur","Feminine: <b>ma</b>."],["___ amie (my)","mon amie","Before a vowel: <b>mon</b>, even feminine."],["___ hôtel (this)","cet hôtel","Before a vowel: <b>cet</b>."],["___ maison (this)","cette maison","Feminine: <b>cette</b>."],["___ voiture (his)","sa voiture","voiture is feminine: <b>sa</b>, whoever owns it."],["___ enfants (their)","leurs enfants","More than one: <b>leurs</b>."]]},"11":{"line":"<b>C'est</b> + a name, or + un / le / mon … + a noun: c'est Paul, c'est un médecin, c'est mon frère. <b>Il / elle est</b> + an adjective, or a job with <b>no article</b>: il est grand, elle est infirmière. About a thing or an idea: c'est beau, c'est facile.","words":"The jobs: <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:11\">Vocab 11 · Professions & Occupations</a>.","steps":[{"tool":"sort","title":"c'est or il / elle est?","sub":"Tap the box for each ending.","boxes":[{"k":"c","label":"C'est","sub":"+ a name, or un / le / mon + a noun"},{"k":"i","label":"Il / elle est","sub":"+ an adjective, or a job alone"}],"cards":[{"t":"… Paul.","box":"c","why":"A name: <b>c'est</b> Paul.","say":"C'est Paul."},{"t":"… médecin.","box":"i","why":"A job alone: <b>il est</b> médecin.","say":"Il est médecin."},{"t":"… un bon médecin.","box":"c","why":"un + a noun: <b>c'est</b> un bon médecin.","say":"C'est un bon médecin."},{"t":"… très grand. (Paul)","box":"i","why":"An adjective: <b>il est</b> très grand.","say":"Il est très grand."},{"t":"… mon frère.","box":"c","why":"mon + a noun: <b>c'est</b> mon frère.","say":"C'est mon frère."},{"t":"… infirmière. (Marie)","box":"i","why":"A job alone: <b>elle est</b> infirmière.","say":"Elle est infirmière."},{"t":"… une amie.","box":"c","why":"une + a noun: <b>c'est</b> une amie.","say":"C'est une amie."},{"t":"… fatiguée. (Léa)","box":"i","why":"An adjective: <b>elle est</b> fatiguée.","say":"Elle est fatiguée."}]},{"tool":"swap","title":"Add un or une, change the start","sub":"Pick a sentence and tap « Add un / une »: il est becomes c'est.","button":["Add un / une","Take it away"],"legend":[["x","the start"],["p","un / une (+ adjective)"]],"items":[{"label":"Il est médecin.","en":["He is a doctor.","He is a good doctor."],"a":[["s","Il est","x"],["o","médecin.",""]],"b":[["s2","C'est","x"],["a","un","p"],["ad","bon","p"],["o","médecin.",""]],"note":"With un / une, <b>il est</b> becomes <b>c'est</b>."},{"label":"Elle est professeure.","en":["She is a teacher.","She is a nice teacher."],"a":[["s","Elle est","x"],["o","professeure.",""]],"b":[["s2","C'est","x"],["a","une","p"],["o","professeure",""],["ad","sympa.","p"]],"note":"<b>c'est une</b> professeure sympa."},{"label":"Il est français.","en":["He is French.","He is a French friend."],"a":[["s","Il est","x"],["o","français.",""]],"b":[["s2","C'est","x"],["a","un","p"],["n","ami","p"],["o","français.",""]],"note":"An adjective alone: il est. un + a noun: <b>c'est</b>."}]}],"practice":{"choose":[{"q":"___ un livre intéressant.","en":"It's an interesting book.","opts":["C'est","Il est","Elle est","Ce"],"a":"C'est","why":"un + a noun follows.","hint":"un + noun: <b>c'est</b>."},{"q":"Marie ? ___ infirmière.","en":"Marie? She is a nurse.","opts":["Elle est","C'est","Elle est une","C'est une"],"a":"Elle est","why":"A job with no article…","hint":"A job alone: <b>elle est</b> infirmière."},{"q":"___ mon frère.","en":"This is my brother.","opts":["C'est","Il est","Il","Ce sont"],"a":"C'est","why":"mon + a noun follows.","hint":"<b>c'est</b> mon frère."},{"q":"Paul ? ___ très grand.","en":"Paul? He is very tall.","opts":["Il est","C'est","Il a","Ce"],"a":"Il est","why":"An adjective follows, about a person.","hint":"<b>il est</b> très grand."},{"q":"Il est ___.","en":"He is a doctor.","opts":["médecin","un médecin","le médecin","une médecin"],"a":"médecin","why":"After il est, a job…","hint":"No article: il est <b>médecin</b>."},{"q":"C'est ___ bon médecin.","en":"He is a good doctor.","opts":["un","le","de","des"],"a":"un","why":"After c'est, a noun takes…","hint":"<b>c'est un</b> bon médecin."},{"q":"Le film ? ___ génial !","en":"The film? It is great!","opts":["C'est","Il est","Elle est","Ce sont"],"a":"C'est","why":"An opinion about a thing…","hint":"Your opinion of a thing: <b>c'est</b> génial."}],"build":[{"en":"She is a nurse.","tiles":["Elle","est","infirmière."],"trap":"une","why":"A job alone: no article.","hint":"elle est <b>infirmière</b>."},{"en":"This is my brother.","tiles":["C'est","mon","frère."],"trap":"Il est","why":"mon + a noun…","hint":"<b>c'est</b> mon frère."},{"en":"He is very tall.","tiles":["Il","est","très","grand."],"trap":"C'est","why":"An adjective about a person…","hint":"<b>il est</b> très grand."},{"en":"It's an interesting book.","tiles":["C'est","un","livre","intéressant."],"trap":"Il est","why":"un + a noun…","hint":"<b>c'est</b> un livre."},{"en":"He is a good doctor.","tiles":["C'est","un","bon","médecin."],"trap":"Il est","why":"un + a noun…","hint":"<b>c'est</b> un bon médecin."}],"spot":[{"words":["Il est","un bon","médecin."],"bad":0,"fix":"C'est","hint":"un + a noun: <b>c'est</b>.","look":"Look at the start."},{"words":["Paul ?","C'est","très grand."],"bad":1,"fix":"Il est","hint":"An adjective about a person: <b>il est</b>.","look":"Is it an adjective or a noun after it?"},{"words":["Il est","mon","frère."],"bad":0,"fix":"C'est","hint":"mon + a noun: <b>c'est</b>.","look":"Look at the start."},{"words":["Marie ?","Elle est","une infirmière."],"bad":2,"fix":"infirmière.","hint":"A job after elle est: no article.","look":"Look after elle est."},{"words":["Il est","Paul."],"bad":0,"fix":"C'est","hint":"A name: <b>c'est</b> Paul.","look":"Look at the start."}]},"drill":[["___ un livre intéressant","C'est un livre intéressant.","un + a noun: <b>c'est</b>."],["She is a nurse","Elle est infirmière.","A job alone: <b>elle est</b> infirmière, no article."],["This is my brother","C'est mon frère. / Voici mon frère.","mon + a noun: <b>c'est</b> mon frère."],["He is very tall","Il est très grand.","An adjective: <b>il est</b> grand."],["He is French.","Il est français.","An adjective: <b>il est</b> français."],["He is a French friend.","C'est un ami français.","un + a noun: <b>c'est</b> un ami."]]},"13":{"line":"What is going to happen: <b>aller</b> in the present + the verb as it is: je <b>vais</b> manger, tu vas partir, il va pleuvoir, nous allons voir. The no goes round aller: je <b>ne vais pas</b> partir. It is the usual way to talk about plans.","words":"","steps":[{"tool":"line","title":"On the time line","sub":"Tap a point: before now, now, or what is going to happen.","now":"","marks":[{"at":-0.8,"label":"hier","fr":"Hier, j'ai mangé chez moi.","en":"Yesterday I ate at home.","note":"Before now: the passé composé (in A2)."},{"at":0.0,"label":"maintenant","fr":"Je mange.","en":"I am eating.","note":"Now: the present."},{"at":0.3,"label":"ce soir","fr":"Ce soir, je vais manger au restaurant.","html":"Ce soir, je <span class=\"gt-end\">vais manger</span> au restaurant.","en":"Tonight I'm going to eat at the restaurant."},{"at":0.6,"label":"demain","fr":"Demain, il va pleuvoir.","html":"Demain, il <span class=\"gt-end\">va pleuvoir</span>.","en":"Tomorrow it's going to rain."},{"at":0.92,"label":"l'été prochain","fr":"L'été prochain, nous allons voyager.","html":"L'été prochain, nous <span class=\"gt-end\">allons voyager</span>.","en":"Next summer we're going to travel."}]},{"tool":"swap","title":"Now → soon","sub":"Pick a sentence and tap « Make it the future »: aller comes in, the verb goes back to its -er, -ir or -re form.","button":["Make it the future","Back to now"],"legend":[["x","aller"],["v","the verb"],["n","ne … pas"]],"items":[{"label":"Je mange.","en":["I am eating.","I am going to eat."],"a":[["s","Je",""],["v","mange.","v"]],"b":[["s","Je",""],["a","vais","x"],["v","manger.","v"]]},{"label":"Nous partons.","en":["We are leaving.","We are going to leave."],"a":[["s","Nous",""],["v","partons.","v"]],"b":[["s","Nous",""],["a","allons","x"],["v","partir.","v"]]},{"label":"Il pleut.","en":["It's raining.","It's going to rain."],"a":[["s","Il",""],["v","pleut.","v"]],"b":[["s","Il",""],["a","va","x"],["v","pleuvoir.","v"]]},{"label":"Elle ne part pas.","en":["She isn't leaving.","She isn't going to leave."],"a":[["s","Elle",""],["ne","ne","n"],["v","part","v"],["pas","pas.","n"]],"b":[["s","Elle",""],["ne","ne","n"],["a","va","x"],["pas","pas","n"],["v","partir.","v"]],"note":"The no goes round <b>va</b>: elle ne va pas partir."}]},{"tool":"conj","title":"aller + the verb","sub":"Tap a person: only aller changes.","neg":true,"verbs":[{"inf":"manger","en":"going to eat","forms":["vais","vas","va","allons","allez","vont"],"tail":"manger"},{"inf":"partir","en":"going to leave","forms":["vais","vas","va","allons","allez","vont"],"tail":"partir"}]}],"practice":{"choose":[{"q":"Nous ___ manger.","en":"We are going to eat.","opts":["allons","allez","vont","vais"],"a":"allons","why":"aller with nous.","hint":"nous <b>allons</b> manger."},{"q":"Je vais ___ demain.","en":"I'm going to leave tomorrow.","opts":["partir","pars","part","parti"],"a":"partir","why":"After vais, the verb…","hint":"It stays as it is: <b>partir</b>."},{"q":"Il ___ pleuvoir.","en":"It's going to rain.","opts":["va","vas","vais","est"],"a":"va","why":"aller with il.","hint":"il <b>va</b> pleuvoir."},{"q":"Elle ne ___ pas venir.","en":"She isn't going to come.","opts":["va","vas","vais","vont"],"a":"va","why":"aller with elle.","hint":"elle ne <b>va</b> pas venir."},{"q":"Ils ___ voyager.","en":"They are going to travel.","opts":["vont","allent","va","allons"],"a":"vont","why":"aller with ils.","hint":"ils <b>vont</b> voyager."},{"q":"Tu ___ voir.","en":"You're going to see.","opts":["vas","va","vais","allez"],"a":"vas","why":"aller with tu.","hint":"tu <b>vas</b> voir."},{"q":"Je ___ t'appeler.","en":"I'm going to call you.","opts":["vais","va","vas","suis"],"a":"vais","why":"aller with je.","hint":"je <b>vais</b> t'appeler."}],"build":[{"en":"We are going to eat.","tiles":["Nous","allons","manger."],"trap":"mangeons","why":"The second verb stays as it is.","hint":"allons <b>manger</b>."},{"en":"She isn't going to leave.","tiles":["Elle","ne","va","pas","partir."],"trap":"part","why":"The no goes round va.","hint":"ne <b>va</b> pas partir."},{"en":"It's going to rain.","tiles":["Il","va","pleuvoir."],"trap":"pleut","why":"The second verb stays as it is.","hint":"va <b>pleuvoir</b>."},{"en":"I'm going to call you.","tiles":["Je","vais","t'appeler."],"trap":"appelle","why":"The second verb stays as it is.","hint":"vais <b>t'appeler</b>."},{"en":"They are going to travel.","tiles":["Ils","vont","voyager."],"trap":"voyagent","why":"The second verb stays as it is.","hint":"vont <b>voyager</b>."}],"spot":[{"words":["Je","vais","mange."],"bad":2,"fix":"manger.","hint":"The second verb stays as it is: <b>manger</b>.","look":"Look at the second verb."},{"words":["Nous","allez","partir."],"bad":1,"fix":"allons","hint":"aller with nous: <b>allons</b>.","look":"Look at aller with nous."},{"words":["Elle","va pas","venir."],"bad":1,"fix":"ne va pas","hint":"The full no: <b>ne va pas</b>.","look":"Something is missing in the no."},{"words":["Il","va","pleut."],"bad":2,"fix":"pleuvoir.","hint":"The second verb stays as it is: <b>pleuvoir</b>.","look":"Look at the second verb."},{"words":["Ils","allent","voyager."],"bad":1,"fix":"vont","hint":"aller with ils: <b>vont</b>.","look":"Look at aller with ils."}]},"drill":[["We are going to eat","Nous allons manger. / On va manger.","aller + the verb as it is: nous <b>allons</b> manger."],["She isn't going to leave","Elle ne va pas partir.","The no goes round aller: elle <b>ne va pas</b> partir."],["I'm going to call you","Je vais t'appeler. / Je vais vous appeler. / Je vais te téléphoner.","je <b>vais</b> + the verb."],["It's going to rain","Il va pleuvoir.","il <b>va</b> pleuvoir."],["They are going to travel.","Ils vont voyager.","ils <b>vont</b> + the verb as it is."],["I'm going to eat.","Je vais manger.","je <b>vais</b> manger."]]},"14":{"line":"To tell someone to do something, take the <b>tu, nous</b> or <b>vous</b> form and drop the subject: Parle ! Parlons ! Parlez ! For -er verbs (and aller), the tu form loses its -s: tu manges → <b>Mange !</b> The no goes round the verb: <b>Ne</b> parle <b>pas</b> ! A few are special: sois, soyez (être), aie (avoir).","words":"","steps":[{"tool":"swap","title":"Drop the subject","sub":"Pick a sentence and tap « Make it an order ».","button":["Make it an order","Back to the sentence"],"legend":[["v","the verb"],["n","ne … pas"]],"items":[{"label":"Tu parles.","en":["You speak.","Speak!"],"a":[["s","Tu",""],["v","parles.","v"]],"b":[["v","Parle !","v"]],"note":"-er verbs: tu parles → <b>Parle !</b> (no -s)."},{"label":"Vous entrez.","en":["You come in.","Come in!"],"a":[["s","Vous",""],["v","entrez.","v"]],"b":[["v","Entrez !","v"]],"note":"Polite, or to several people: <b>Entrez !</b>"},{"label":"Nous partons.","en":["We are leaving.","Let's go!"],"a":[["s","Nous",""],["v","partons.","v"]],"b":[["v","Partons !","v"]],"note":"The nous form = « let's »: <b>Partons !</b>"},{"label":"Tu attends.","en":["You wait.","Wait!"],"a":[["s","Tu",""],["v","attends.","v"]],"b":[["v","Attends !","v"]],"note":"Not an -er verb: the -s stays: <b>Attends !</b>"},{"label":"Tu ne parles pas.","en":["You don't speak.","Don't speak!"],"a":[["s","Tu",""],["ne","ne","n"],["v","parles","v"],["pas","pas.","n"]],"b":[["ne","Ne","n"],["v","parle","v"],["pas","pas !","n"]],"note":"The no goes round the verb: <b>Ne parle pas !</b>"},{"label":"Tu vas au lit.","en":["You go to bed.","Go to bed!"],"a":[["s","Tu",""],["v","vas","v"],["o","au lit.",""]],"b":[["v","Va","v"],["o","au lit !",""]],"note":"aller loses its -s too: <b>Va !</b>"}]},{"tool":"sort","title":"tu, nous or vous?","sub":"Who is it for? Tap the box.","boxes":[{"k":"tu","label":"tu","sub":"one person you know well"},{"k":"nous","label":"nous","sub":"let's (you and me)"},{"k":"vous","label":"vous","sub":"polite, or several"}],"cards":[{"t":"Viens !","box":"tu"},{"t":"Venez !","box":"vous"},{"t":"Allons-y !","box":"nous","why":"<b>Allons-y</b> = let's go."},{"t":"Mange !","box":"tu"},{"t":"Écoutez !","box":"vous"},{"t":"Partons !","box":"nous"},{"t":"Attends !","box":"tu"}]},{"tool":"flip","title":"The special ones","sub":"Tap a card.","cards":[{"a":"être (tu)","b":"Sois sage !","tag":"être → sois","en":"be good"},{"a":"être (vous)","b":"Soyez à l'heure !","tag":"être → soyez","en":"be on time"},{"a":"avoir (tu)","b":"N'aie pas peur !","tag":"avoir → aie","en":"don't be afraid"},{"a":"aller (tu)","b":"Va !","tag":"tu vas → va","en":"go"},{"a":"faire (tu)","b":"Fais attention !","tag":"faire → fais","en":"be careful"}]}],"practice":{"choose":[{"q":"Tell a friend: ___ ! (wait)","en":"Wait!","opts":["Attends","Attend","Attendez","Tu attends"],"a":"Attends","why":"A friend: the tu form, no subject.","hint":"<b>Attends !</b>"},{"q":"Tell your boss: ___ ! (come in)","en":"Come in!","opts":["Entrez","Entre","Entrons","Vous entrez"],"a":"Entrez","why":"Polite: the vous form, no subject.","hint":"<b>Entrez !</b>"},{"q":"___ ! (Let's go)","en":"Let's go!","opts":["Allons-y","Allez-y","Va","Vont"],"a":"Allons-y","why":"Let's = the nous form.","hint":"<b>Allons-y !</b>"},{"q":"___ ! (eat, tu)","en":"Eat!","opts":["Mange","Manges","Mangez","Tu manges"],"a":"Mange","why":"-er verbs with tu lose something.","hint":"<b>Mange !</b> (no -s)."},{"q":"Ne ___ pas en retard ! (tu, être)","en":"Don't be late!","opts":["sois","es","être","soit"],"a":"sois","why":"être has a special form.","hint":"Ne <b>sois</b> pas en retard !"},{"q":"___ attention ! (tu, faire)","en":"Be careful!","opts":["Fais","Fait","Faire","Faites"],"a":"Fais","why":"faire with tu.","hint":"<b>Fais</b> attention !"},{"q":"Ne ___ pas ! (tu, parler)","en":"Don't speak!","opts":["parle","parles","parlez","parler"],"a":"parle","why":"-er verbs with tu…","hint":"Ne <b>parle</b> pas !"}],"build":[{"en":"Come in, please! (vous)","tiles":["Entrez,","s'il","vous","plaît !"],"trap":"Vous entrez","why":"No subject in an order.","hint":"<b>Entrez</b>, …"},{"en":"Don't be late! (tu)","tiles":["Ne","sois","pas","en retard !"],"trap":"es","why":"être has a special form.","hint":"Ne <b>sois</b> pas …"},{"en":"Let's go to the park!","tiles":["Allons","au","parc !"],"trap":"Nous","why":"No subject in an order.","hint":"<b>Allons</b> au parc !"},{"en":"Eat your soup! (tu)","tiles":["Mange","ta","soupe !"],"trap":"Manges","why":"-er verbs with tu lose the -s.","hint":"<b>Mange</b> ta soupe !"},{"en":"Don't talk! (vous)","tiles":["Ne","parlez","pas !"],"trap":"Vous","why":"No subject in an order.","hint":"Ne <b>parlez</b> pas !"}],"spot":[{"words":["Manges","ta soupe !"],"bad":0,"fix":"Mange","hint":"-er verbs lose the -s: <b>Mange !</b>","look":"Look at the end of the verb."},{"words":["Tu attends !"],"bad":0,"fix":"Attends !","hint":"No subject in an order: <b>Attends !</b>","look":"Is the subject needed?"},{"words":["Ne","es","pas en retard !"],"bad":1,"fix":"sois","hint":"être: <b>sois</b>.","look":"être has a special form."},{"words":["Parle","pas !"],"bad":0,"fix":"Ne parle","hint":"The full no: <b>Ne parle pas !</b>","look":"Something is missing in the no."},{"words":["Vas","au lit !"],"bad":0,"fix":"Va","hint":"aller loses its -s: <b>Va !</b>","look":"Look at the end of the verb."}]},"drill":[["Tell a friend: wait!","Attends !","The tu form, no subject: <b>Attends !</b>"],["Tell your boss: come in!","Entrez !","Polite: the vous form, <b>Entrez !</b>"],["Let's go!","Allons-y ! / On y va !","Let's = the nous form: <b>Allons-y !</b>"],["Don't be late (tu)","Ne sois pas en retard !","être → <b>sois</b>; the no goes round it."],["Tell a friend: eat!","Mange !","-er verbs drop the -s: <b>Mange !</b>"],["Tell two friends: listen!","Écoutez !","More than one person: the vous form, <b>Écoutez !</b>"]]}};
